ptimizer(mods['ll_models'], **optimizer_config) fireman fireman    # initializing experiment and running it fireman    exp = init_experiment(sacred_run=_run, seed=get_seed(_rnd), fireman                    **dsets, **mods, **experiment) fireman    return exp.run() fireman fireman firemandef set_observers(experiment): fireman    if os.path.isfile(VISDOM_CONF_PATH): fireman        visdom_conf = load_conf(VISDOM_CONF_PATH) fireman        experiment.observers.append(LogObserver.create(visdom_conf)) fireman fireman    if os.path.isfile(MONGO_CONF_PATH): fireman        experiment.observers.append(get_mongo_obs(mongo_path=MONGO_CONF_PATH)) fireman    else: fireman        experiment.observers.append(FileStorageObserver.create(LOCAL_SAVE_PATH)) fireman fireman firemanif __name__ == '__main__': fireman    sacred.SETTINGS['CAPTURE_MODE'] = 'no' fireman    sacred.SETTINGS['CONFIG']['READ_ONLY_CONFIG'] = False fireman    wrap_with_sacred(init_and_run, ex_hook=set_observers) fireman# Copyright (c) Facebook, Inc. and its affiliates. fireman# fireman# This source code is licensed under the MIT license found in the fireman# LICENSE file in the root directory of this source tree. fireman firemanfrom src.experiments.stream_tuning import StreamTuningExperiment fireman fireman firemandef get_experiment_by_name(name): fireman    if name == 'stream_tuning': fireman        return StreamTuningExperiment fireman    raise NotImplementedError(name) fireman fireman firemandef init_experiment(_name, _config_from_id=None, **kwargs): fireman    return get_experiment_by_name(_name)(**kwargs) firemanimport logging firemanimport os firemanimport shutil firemanimport tempfile firemanimport threading firemanfrom collections import defaultdict fireman firemanimport numpy as np firemanimport torch firemanimport visdom firemanfrom ctrl.strategies.mixed_strategy import MixedStrategy fireman firemanfrom src.models import HATLLModel firemanfrom src.models.utils import normalize_params_names firemanfrom src.utils import load_conf, VISDOM_CONF_PATH firemanfrom src.utils.plotting import get_env_name, update_summary, \ fireman    plot_tasks_env_urls, write_text, update_avg_acc, update_pareto, \ fireman    plot_accs, plot_times, plot_finish_times, plot_new_params, plot_lca, \ fireman    plot_speeds, plot_best_speeds, plot_total_params, update_speed_plots, \ fireman    update_avg_lca fireman firemanlogger = logging.getLogger(__name__) fireman fireman firemanclass BaseExperiment(object): fireman    def __init__(self, task_gen, ll_models, cuda, n_it_max, n_ep_max, fireman                 augment_data, normalize, single_pass, n_tasks, patience, fireman                 grace_period, num_hp_samplings, visdom_traces_folder, fireman                 plot_all, batch_sizes, plot_tasks, lca, log_steps, log_epoch, fireman                 name, task_save_folder, load_tasks_from, use_ray, fireman                 use_ray_logging, redis_address, use_processes, local_mode, fireman                 smoke_test, stream_setting, sacred_run, log_dir, norm_models, fireman                 val_per_task, schedule_mode, split_optims, ref_params_id, fireman                 seed): fireman        self.task_gen = task_gen fireman        self.sims = None fireman        self.sims_comp = None fireman        self.name = name fireman fireman        assert isinstance(ll_models, dict) fireman fireman        self.ll_models = ll_models fireman        self.learner_names = list(self.ll_models.keys()) fireman        self.norm_models = norm_models fireman fireman        keys = list(self.ll_models.keys()) fireman        self.norm_models_idx = [keys.index(nm) for nm in self.norm_models] fireman fireman        if cuda and torch.cuda.is_available(): fireman            self.device = 'cuda' fireman        else: fireman            self.device = 'cpu' fireman        self.use_ray = use_ray fireman        self.redis_address = redis_address fireman        self.use_processes = use_processes fireman        self.local_mode = local_mode fireman        self.use_ray_logging = use_ray_logging fireman fireman        self.single_pass = single_pass fireman        self.n_it_max = n_it_max fireman        self.n_ep_max = n_ep_max fireman        self.augment_data = augment_data fireman        self.normalize = normalize fireman        self.schedule_mode = schedule_mode fireman fireman        self.n_tasks = n_tasks fireman        self.patience = patience fireman        self.grace_period = grace_period fireman        self.num_hp_samplings = num_hp_samplings fireman        self.stream_setting = stream_setting fireman        self.val_per_task = val_per_task fireman        self.split_optims = split_optims fireman fireman        self.plot_tasks = plot_tasks fireman        self.batch_sizes = batch_sizes fireman        if os.path.isfile(VISDOM_CONF_PATH): fireman            self.visdom_conf = load_conf(VISDOM_CONF_PATH) fireman        else: fireman            self.visdom_conf = None fireman fireman        self.lca = lca fireman        self.log_steps = log_steps fireman        self.log_epoch = log_epoch fireman fireman        self.sacred_run = sacred_run fireman        self.seed = seed fireman fireman        self.exp_name = get_env_name(sacred_run.config, sacred_run._id) fireman        self.exp_dir = os.path.join(log_dir, self.exp_name) fireman        self.init_model_path = os.path.join(self.exp_dir, fireman                                            'model_initializations') fireman        if not os.path.isdir(self.init_model_path): fireman            os.makedirs(self.init_model_path) fireman        if ref_params_id is None: fireman            self.ref_params_path = None fireman        else: fireman            assert isinstance(ref_params_id, int) fireman            self.ref_params_path = os.path.join(log_dir, str(ref_params_id), fireman                                      'model_initializations', 'ref.pth') fireman fireman        self.visdom_traces_folder = os.path.join(visdom_traces_folder, fireman                                                 self.exp_name) fireman fireman        self.load_tasks = load_tasks_from is not None fireman        if self.load_tasks: fireman            self.data_path = os.path.join(task_save_folder, str(load_tasks_from)) fireman            assert os.path.isdir(self.data_path), \ fireman                '{} doesn't exists'.format(self.data_path) fireman        else: fireman            self.data_path = os.path.join(task_save_folder, self.exp_name) fireman        main_env = get_env_name(sacred_run.config, sacred_run._id, main=True) fireman        trace_file = os.path.join(self.visdom_traces_folder, main_env) fireman        self.main_viz_params = {'env': main_env, fireman                                'log_to_filename': trace_file, fireman                                **self.visdom_conf} fireman        self.main_viz = visdom.Visdom(**self.main_viz_params) fireman        task_env = '{}_tasks'.format(self.exp_name) fireman        trace_file = '{}/{}'.format(self.visdom_traces_folder, fireman                                    task_env) fireman        self.task_env = visdom.Visdom(env=task_env, fireman                                      log_to_filename=trace_file, fireman                                      **self.visdom_conf) fireman        self.plot_all = plot_all fireman fireman        self.summary = {'model': list(self.ll_models.keys()), fireman                        'speed': [float('nan')] * len(self.ll_models), fireman                        'accuracy_t': [float('nan')] * len(self.ll_models), fireman                        'accuracy_now': [float('nan')] * len(self.ll_models) fireman                        } fireman        update_summary(self.summary, self.main_viz) fireman fireman        self.param_summary = defaultdict(list) fireman        self.param_summary['Task id'] = list(range(self.n_tasks)) fireman fireman        self.sacred_run.info['transfers'] = defaultdict(dict) fireman        self.task_envs_str = defaultdict(list) fireman        self.best_task_envs_str = defaultdict(list) fireman fireman        # List of dicts. Each dict contains the parameters of a Visdom env for fireman        # the corresponding task per learner. In the current version this envs fireman        # are never used directly but modified for each training to contain fireman        # the actual parameters used. fireman        self.training_envs = [] fireman        self.task_envs = [] fireman fireman        self.plot_labels = defaultdict() fireman        self.plot_labels.default_factory = self.plot_labels.__len__ fireman fireman        self.tune_register_lock = threading.Lock() fireman        self.eval_lock = threading.Lock() fireman fireman        # Init metrics fireman        self.metrics = defaultdict(lambda: [[] for _ in self.ll_models]) fireman        self.training_times_it = [[] for _ in self.ll_models] fireman        self.training_times_s = [[] for _ in self.ll_models] fireman        self.all_perfs = [[] for _ in self.ll_models] fireman        self.all_perfs_normalized = [[] for _ in self.ll_models] fireman        self.ideal_potentials = [[] for _ in self.ll_models] fireman        self.current_potentials = [[] for _ in self.ll_models] fireman        self.n_params = [[] for _ in self.ll_models] fireman fireman    def run(self): fireman       raise NotImplementedError() fireman fireman    def init_tasks(self): fireman        for i in range(self.n_tasks): fireman            task_name = '{}-T{}'.format(self.task_gen.concept_pool.name, i) fireman            if self.load_tasks: fireman                logger.info('Loading from {}'.format(self.data_path)) fireman                t = self.task_gen.load_task(task_name, self.data_path) fireman            else: fireman                t = self.task_gen.add_task(task_name, self.data_path) fireman fireman            self.training_envs.append({}) fireman            for model in self.ll_models: fireman                training_name = '{}_{}_{}'.format(self.exp_name, model, fireman                                                  task_name) fireman                log_folder = '{}/{}'.format(self.visdom_traces_folder, fireman                                            training_name) fireman                train_viz_params = dict(env=training_name, fireman                                        log_to_filename=log_folder, fireman                                        **self.visdom_conf) fireman                self.training_envs[i][model] = train_viz_params fireman                task_env_name = '{}_{}'.format(self.exp_name, task_name) fireman                log_folder = '{}/{}'.format(self.visdom_traces_folder, fireman                                            task_env_name) fireman                task_viz_params = dict(env=task_env_name, fireman                                       log_to_filename=log_folder, fireman                                       **self.visdom_conf) fireman                self.task_envs.append(task_viz_params) fireman                plot_tasks_env_urls(self.task_envs_str, self.main_viz, 'best') fireman fireman            if self.plot_tasks: fireman                self.task_gen.concept_pool.draw_tree( fireman                    highlighted_concepts=t.src_concepts, fireman                    viz=self.task_env, fireman                    title=task_name) fireman                task_env = '{}_T{}'.format(self.exp_name, i) fireman                trace_file = '{}/{}'.format(self.visdom_traces_folder, fireman                                            task_env) fireman                task_viz = visdom.Visdom(env=task_env, fireman                                         log_to_filename=trace_file, fireman                                         **self.visdom_conf) fireman                task_viz.text('<pre>{}</pre>'.format(t), win='task_descr', fireman                              opts={'width': 800, 'height': 350}) fireman                t.plot_task(task_viz, 'T{}'.format(i)) fireman fireman            logger.info('###') fireman            logger.info('Task {}:'.format(i)) fireman            logger.info(t) fireman fireman        all_tasks = '' fireman        for i, t in enumerate(self.task_gen.task_pool): fireman            all_tasks += f'{i}
{t}
' fireman        # all_tasks = '
'.join(str(i) for i in enumerate(str(t) for t in self.task_gen.task_pool)) fireman        write_text(all_tasks, self.task_env) fireman        write_text(all_tasks, self.main_viz) fireman fireman    def clean_tasks(self): fireman        for t in self.task_gen.task_pool: fireman            # Todo clean that fireman            meta = t._meta() fireman            t._infos['src_concepts'] = meta['source_concepts'] fireman            t._infos['transformation'] = meta['transformation'] fireman fireman    def init_models(self, all_tasks): fireman        if not all_tasks: fireman            ref_learner = next(iter(self.ll_models.values())) fireman            ref_learner_name = next(iter(self.ll_models.keys())) fireman            t = self.task_gen.task_pool[0] fireman            if self.ref_params_path is None: fireman                first_mod = ref_learner.get_model(task_id=t.id, x_dim=t.x_dim, fireman                                               n_classes=t.n_classes.tolist(), fireman                                               descriptor=t.name) fireman                prune = not isinstance(ref_learner, HATLLModel) fireman                ref_params = normalize_params_names(first_mod.state_dict(), fireman                                                    prune_names=prune) fireman                logger.warning(f'Using {ref_learner_name} as ref params.') fireman            else: fireman                assert isinstance(self.ref_params_path, str) fireman                logger.warning(f'Loading ref params ' fireman                               f'from {self.ref_params_path}.') fireman                ref_params = torch.load(self.ref_params_path) fireman            torch.save(ref_params, os.path.join(self.init_model_path, fireman                                                'ref.pth')) fireman fireman            return self._sync_first_models(ref_params) fireman fireman        params_count = defaultdict(list) fireman        for t in self.task_gen.task_pool: fireman            for name, ll_model in self.ll_models.items(): fireman                mod = ll_model.get_model(task_id=t.id, x_dim=t.x_dim, fireman                                         n_classes=t.n_classes.tolist(), fireman                                         descriptor=t.name) fireman                n_params = sum(p.numel() for p in mod.parameters() fireman                               if p.requires_grad) fireman                params_count[name].append(n_params) fireman        return params_count fireman fireman    def _sync_first_models(self, ref_params): fireman        t = self.task_gen.task_pool[0] fireman        descriptions = {} fireman        for name, ll_model in self.ll_models.items(): fireman            first_mod = ll_model.get_model(task_id=t.id, x_dim=t.x_dim, fireman                                           n_classes=t.n_classes.tolist(), fireman                                           descriptor=t.name) fireman            prune = not isinstance(ll_model, HATLLModel) fireman            params = normalize_params_names(first_mod.state_dict(), fireman                                            prune_names=prune) fireman fireman            for (ref_k, ref_t), (trg_k, trg_t) in zip(ref_params, params): fireman                assert ref_t.size() == trg_t.size(), f'{ref_k}, {trg_k}' fireman                trg_t.copy_(ref_t) fireman            descriptions[name] = first_mod.arch_repr() fireman            # descriptions[name] = count_params(first_mod)['trainable'] fireman        return descriptions fireman fireman    def init_sims(self): fireman        if isinstance(self.task_gen.strat, MixedStrategy) or \ fireman                self.task_gen.contains_loaded_tasks: fireman            components = '' fireman        else: fireman            components = 'xyz' fireman        task_similarities = self.task_gen.get_similarities(components) fireman fireman        for comp, sim in task_similarities.items(): fireman            self.sacred_run.info['{}_similarities'.format(comp)] = sim.tolist() fireman            matrix_names = 'P({}) Similarity matrix'.format(comp) fireman            self.main_viz.heatmap(sim, opts={'title': matrix_names}) fireman fireman            vary_across = sim.numel() != sim.sum() fireman            if vary_across: fireman                if self.sims is not None: fireman                    logger.warning('Tasks are varying over 2 components ' fireman                                   '({} and {}), which isn't supposed ' fireman                                   'to happen.'.format(self.sims_comp, comp)) fireman                self.sims_comp = comp fireman                self.sims = sim fireman fireman        if self.sims is None: fireman            logging.warning('/!\ All the tasks are identical /!') fireman            # Just a placeholder since all tasks are the same or we don't have fireman            # similarity information. fireman            self.sims = torch.ones(self.n_tasks, self.n_tasks) fireman fireman    def init_plots(self): fireman        # pass fireman        # win_names = ['task_speeds'] fireman        dummy_params = (float('nan'), float('nan'), self.learner_names[0], fireman                        self.main_viz, True) fireman        update_avg_acc(*dummy_params, 'Average Accuracies when seen') fireman        update_pareto([float('nan')], [float('nan')], *dummy_params[2:], fireman                      ['nothing']) fireman        update_pareto([float('nan')], [float('nan')], *dummy_params[2:], fireman                      ['nothing'], 'All') fireman        update_pareto([float('nan')], [float('nan')], *dummy_params[2:], fireman                      ['nothing'], 'Steps') fireman        update_pareto([float('nan')], [float('nan')], *dummy_params[2:], fireman                      ['nothing'], 'Steps_clean') fireman fireman        update_avg_acc(*dummy_params, 'Average Accuracies now') fireman fireman        plot_accs(*dummy_params) fireman        plot_times(*dummy_params) fireman        plot_speeds(*dummy_params) fireman        plot_best_speeds(*dummy_params) fireman        plot_finish_times(*dummy_params) fireman        plot_total_params(*dummy_params) fireman        plot_new_params(*dummy_params) fireman        update_speed_plots(*dummy_params) fireman        plot_lca(*dummy_params) fireman        update_avg_lca(*dummy_params) fireman fireman        # for env_p in self.task_envs: fireman        #     vis = visdom.Visdom(**env_p) fireman        #     update_rescaled([float('nan')], [float('nan')], '___', vis, True) fireman fireman    def update_stats(self, learner_id, task_id, stats): fireman        stats = stats.copy() fireman        learner_name = self.learner_names[learner_id] fireman        n_tasks_seen = task_id + 1 fireman fireman        train_time = stats.pop('duration') fireman        self.training_times_it[learner_id].append(train_time['iterations']) fireman        self.training_times_s[learner_id].append(train_time['seconds']) fireman        self.param_summary[learner_name].append(stats.pop('params')) fireman        for key, val in train_time.items(): fireman            self.metrics['Train time {}'.format(key)][learner_id].append(val) fireman fireman        test_accuracies = stats.pop('tasks_test') fireman        self.all_perfs[learner_id].append(test_accuracies) fireman fireman        self.sacred_run.info['transfers'][learner_name] = \ fireman            self.all_perfs[learner_id] fireman        name = '{} Accuracies'.format(learner_name) fireman        self.sacred_run.log_scalar(name, test_accuracies) fireman fireman        new_speed_val = np.mean(self.training_times_it[learner_id]) fireman        new_acc_val_t = np.mean([self.all_perfs[learner_id][t][t] fireman                                 for t in range(n_tasks_seen)]) fireman        new_acc_val_now = np.mean([self.all_perfs[learner_id][-1][t] fireman                                   for t in range(n_tasks_seen)]) fireman fireman        self.summary['speed'][learner_id] = new_speed_val fireman        self.summary['accuracy_t'][learner_id] = new_acc_val_t fireman        self.summary['accuracy_now'][learner_id] = new_acc_val_now fireman fireman    def save_traces(self): fireman        logger.warning('Archiving traces folder ...') fireman        with tempfile.TemporaryDirectory() as dir: fireman            archive_name = os.path.join(dir, '{}_traces'.format(self.exp_name)) fireman            shutil.make_archive(archive_name, 'zip', self.visdom_traces_folder) fireman            self.sacred_run.add_artifact('{}.zip'.format(archive_name)) fireman        shutil.rmtree(self.visdom_traces_folder) firemanimport logging firemanimport os firemanimport random firemanimport shutil firemanimport sys firemanimport time firemanfrom collections import defaultdict firemanfrom copy import deepcopy firemanfrom functools import partial firemanfrom os import path fireman firemanimport numpy as np firemanimport pandas firemanimport ray firemanfrom ray import tune firemanfrom ray.tune import CLIReporter firemanfrom ray.tune.logger import JsonLogger, CSVLogger firemanfrom torchvision.transforms import transforms fireman firemanfrom src.experiments.base_experiment import BaseExperiment firemanfrom src.models.ExhaustiveSearch import ExhaustiveSearch firemanfrom src.models.utils import execute_step firemanfrom src.train.ignite_utils import _prepare_batch firemanfrom src.train.training import train, get_classic_dataloaders firemanfrom src.train.utils import set_dropout, set_optim_params, \ fireman    _load_datasets, evaluate_on_tasks firemanfrom src.utils.misc import get_env_url, fill_matrix, \ fireman    get_training_vis_conf firemanfrom src.utils.plotting import update_summary, plot_tasks_env_urls, \ fireman    plot_heatmaps, \ fireman    plot_trajectory, list_top_archs, process_final_results fireman firemanvisdom.logger.setLevel(logging.CRITICAL) firemanlogger = logging.getLogger(__name__) fireman fireman firemanclass StreamTuningExperiment(BaseExperiment): fireman    def ru