an fireman    stats = {} fireman    eval_time = time.time() - start5 fireman fireman    stats.update(finish_res) fireman fireman    test_accs = metrics['Test accuracy_0'] fireman    if not test_accs: fireman        lca = np.float('nan') fireman    else: fireman        if len(test_accs) <= lca_n: fireman            last_key = max(test_accs.keys()) fireman            assert len(test_accs) == last_key + 1,\ fireman                f"Can't compute LCA@{lca_n} if steps were skipped " \ fireman                f"(got {list(test_accs.keys())})" fireman            test_accs = test_accs.copy() fireman            last_acc = test_accs[last_key] fireman            for i in range(last_key + 1, lca_n+1): fireman                test_accs[i] = last_acc fireman        lca = np.mean([test_accs[i] for i in range(lca_n + 1)]) fireman fireman    accs = {} fireman    key = 'accuracy' fireman    # logger.warning(evaluation) fireman    for split in evaluation.keys(): fireman        transfer_matrix[split].append(evaluation[split][key]) fireman        for i in range(len(tasks)): fireman            split_acc = evaluation[split][key] fireman            if i < len(split_acc): fireman                accs['{}_T{}'.format(split, i)] = split_acc[i] fireman            else: fireman                accs['{}_T{}'.format(split, i)] = float('nan') fireman    plot_heatmaps(list(transfer_matrix.keys()), fireman                  list(map(fill_matrix, transfer_matrix.values())), fireman                  task_vis) fireman fireman fireman    # logger.warning(t_id) fireman    # logger.warning(transfer_matrix) fireman fireman    avg_val = np.mean(evaluation['Val']['accuracy']) fireman    avg_val_so_far = np.mean(evaluation['Val']['accuracy'][:t_id+1]) fireman    avg_test = np.mean(evaluation['Test']['accuracy']) fireman    avg_test_so_far = np.mean(evaluation['Test']['accuracy'][:t_id+1]) fireman fireman    step_time_s = time.time() - start1 fireman    step_sum = model_creation_time + training_time + postproc_time