ain_func fireman        t, metrics, b_state_dict = f(datasets_p=datasets_p, fireman                                     b_sizes=batch_sizes, fireman                                     optim_fact=optim_fact, fireman                                     # lr_scheduler=lr_scheduler, fireman                                     # viz=task_vis, fireman                                     prepare_batch=prepare_batch, fireman                                     split_names=task['split_names'], fireman                                     # viz=task_vis, fireman                                     **training_params) fireman        rescaled = list( fireman            filter(lambda itm: 'rescaled' in itm[0], metrics.items())) fireman        rescaled = rescaled[0][1] fireman    else: fireman        optim = optim_fact(model=model) fireman        if hasattr(model, 'train_loader_wrapper'): fireman            train_loader = model.train_loader_wrapper(train_loader) fireman        t, metrics, b_state_dict = train(model, train_loader, eval_loaders, fireman                                         optimizer=optim, fireman                                         # lr_scheduler=lr_scheduler, fireman                                         # viz=task_vis, fireman                                         prepare_batch=prepare_batch, fireman                                         split_names=task['split_names'], fireman                                         # viz=task_vis, fireman                                         **training_params) fireman        rescaled = metrics['Val accuracy_0'] fireman fireman    return rescaled, t, metrics, b_state_dict fireman# Copyright (c) Facebook, Inc. and its affiliates. fireman# fireman# This source code is licensed under the MIT license found in the fireman# LICENSE file in the root directory of this source tree. fireman firemanimport abc firemanimport logging firemanimport os firemanimport time firemanfrom functools import partial fireman firemanimport