Error fireman fireman    def n_params(self, t_id): fireman        """ fireman        Return the total number of parameters used by the lifelong learner for fireman        models up to the task with id `t_id` (included). fireman        :param t_id: fireman        :return: fireman        """ fireman        all_params = set() fireman        for i in range(t_id+1): fireman            model = self.get_model(i) fireman            all_params.update(model.parameters()) fireman            all_params.update(model.buffers()) fireman fireman        return sum(map(torch.numel, all_params)) fireman fireman    def new_params(self, t_id): fireman        return self.n_params(t_id) - self.n_params(t_id-1) fireman fireman    def get_search_space(self): fireman        # params = {k: tune.grid_search(v) for k, v in self.grid_params.items()} fireman        # return params fireman        return convert_to_tune_search_space(self.grid_params) fireman fireman    def finish_task(self, dataset, task_id, viz=None, path=None): fireman        """ fireman        Use the datastet to perform reauired post taks operations and compute fireman        statistics to track. fireman fireman        :param dataset: fireman        :param task_id: fireman        :param viz: fireman        :return: fireman        """ fireman        return {} fireman fireman    def forward(self, *input): fireman        raise NotImplementedError fireman fireman    def train_model_on_task(self, task, task_viz, exp_dir, use_ray, fireman                            use_ray_logging, grace_period, fireman                            num_hp_samplings, local_mode, fireman                            redis_address, lca_n, **training_params): fireman        logger.info("Training dashboard: {}".format(get_env_url(task_viz))) fireman        t_id = task['id'] fireman fireman        trainable = self.get_trainable(use_ray_logging=use_ray_logging) fireman        past_tasks = training_params.pop('past_tasks') fireman        normalize = training_par