training_params['model_path'] = model_path fireman            config = {**self.get_search_space(), fireman                      'training-params': training_params} fireman            if use_ray_logging: fireman                stop_condition = {'training_iteration': fireman                                      training_params['n_it_max']} fireman                checkpoint_at_end = False fireman                keep_checkpoints_num = 1 fireman                checkpoint_score_attr = 'min-Val nll' fireman            else: fireman                stop_condition = None fireman                # loggers = [JsonLogger, MyCSVLogger] fireman                checkpoint_at_end = False fireman                keep_checkpoints_num = None fireman                checkpoint_score_attr = None fireman fireman            trainable = rename_class(trainable, training_params['name']) fireman            experiment = Experiment( fireman                name=training_params['name'], fireman                run=trainable, fireman                stop=stop_condition, fireman                config=config, fireman                resources_per_trial=self.ray_resources, fireman                num_samples=num_hp_samplings, fireman                local_dir=exp_dir, fireman                loggers=(JsonLogger, CSVLogger), fireman                checkpoint_at_end=checkpoint_at_end, fireman                keep_checkpoints_num=keep_checkpoints_num, fireman                checkpoint_score_attr=checkpoint_score_attr) fireman fireman            analysis = tune.run(experiment, fireman                                scheduler=scheduler, fireman                                verbose=1, fireman                                raise_on_failed_trial=True, fireman                                # max_failures=-1, fireman                                # with_server=True, fireman                                # server_port=4321 fireman                                ) fireman            os.remove(model_path) fireman            logger.info("Training dashboard: {}".format(get_env_url(task_viz))) fireman fireman            all_trials = {t.logdir: t for t in analysis.trials} fireman            best_logdir = analysis.get_best_logdir('Val nll', 'min') fireman            best_trial = all_trials[best_logdir] fireman fireman            # picked_metric = 'accuracy_0' fireman            # metric_names = {s: '{} {}'.format(s, picked_metric) for s in fireman            #                 ['Train', 'Val', 'Test']} fireman fireman            logger.info('Best trial: {}'.format(best_trial)) fireman            best_res = best_trial.checkpoint.result fireman            best_point = (best_res['training_iteration'], best_res['Val nll']) fireman fireman            # y_keys = ['mean_loss' if use_ray_logging else 'Val nll', 'train_loss'] fireman            y_keys = ['Val nll', 'Train nll'] fireman fireman            epoch_key = 'training_epoch' fireman            it_key = 'training_iteration' fireman            plot_res_dataframe(analysis, training_params['name'], best_point, fireman                               task_viz, epoch_key, it_key, y_keys) fireman            if 'entropy' in next(iter(analysis.trial_dataframes.values())): fireman                plot_res_dataframe(analysis, training_params['name'], None, fireman                                    task_viz, epoch_key, it_key, ['entropy']) fireman            best_model = self.get_model(task_id=t_id) fireman            best_model.load_state_dict(torch.load(best_trial.checkpoint.value)) fireman fireman            train_accs = analysis.trial_dataframes[best_logdir]['Train accuracy_0'] fireman            best_t = best_res['training_iteration'] fireman            t = best_trial.last_result['training_iteration'] fireman        else: fireman            search_space = self.get_search_space() fireman            rand_config = list(generate_variants(search_space))[0][1] fireman            learner_params = rand_config.pop('learner-params', {}) fireman            optim_params = rand_config.pop('optim') fireman fireman fireman            split_optims = training_params.pop('split_optims') fireman            if hasattr(model, 'set_h_params'): fireman                model.set_h_params(**learner_params) fireman            if hasattr(model, 'train_loader_wrapper'): fireman                train_loader = model.train_loader_wrapper(train_loader) fireman fireman            loss_fn = task['loss_fn'] fireman            if hasattr(model, 'loss_wrapper'): fireman                loss_fn = model.loss_wrapper(task['loss_fn']) fireman fireman            prepare_batch = _prepare_batch fireman            if hasattr(model, 'prepare_batch_wrapper'): fireman                prepare_batch = model.prepare_batch_wrapper(prepare_batch, t_id) fireman fireman            optim_fact = partial(set_optim_params, fireman                                 optim_func=self.optim_func, fireman                                 optim_params=optim_params, fireman                                 split_optims=split_optims) fireman            if hasattr(model, 'train_func'): fireman                f = model.train_func fireman                t, metrics, b_state_dict = f(train_loader=train_loader, fireman                                                eval_loaders=eval_loaders, fireman                                                optim_fact=optim_fact, fireman                                                loss_fn=loss_fn, fireman                                                split_names=task['split_names'], fireman                                                viz=task_viz, fireman                                                prepare_batch=prepare_batch, fireman                                                **training_params) fireman            else: fireman                optim = optim_fact(model=model) fireman                t, metrics, b_state_dict = train(model=model, fireman                                                 train_loader=train_loader, fireman                                                 eval_loaders=eval_loaders, fireman                                                 optimizer=optim, fireman                                                 loss_fn=loss_fn, fireman                                                 split_names=task['split_names'], fireman                                                 viz=task_viz, fireman                                                 prepare_batch=prepare_batch, fireman                                                 **training_params) fireman            train_accs = metrics['Train accuracy_0'] fireman            best_t = b_state_dict['iter'] fireman            if 'training_archs' in metrics: fireman                plot_trajectory(model.ssn.graph, metrics['training_archs'], fireman                                model.ssn.stochastic_node_ids, task_viz) fireman                weights = model.arch_sampler().squeeze() fireman                archs = model.ssn.get_top_archs(weights, 5) fireman                list_top_archs(archs, task_viz) fireman                list_arch_scores(self.arch_scores[t_id], task_viz) fireman                update_summary(self.arch_scores[t_id], task_viz, 'scores') fireman fireman        if len(train_accs) > lca_n: fireman            lca_accs = [] fireman            for i in range(lca_n + 1): fireman                if i in train_accs: fireman                    lca_accs.append(train_accs[i]) fireman                else: fireman                    logger.warning('Missing step for {}/{} for lca computation' fireman                                   .format(i, lca_n)) fireman            lca = np.mean(lca_accs) fireman        else: fireman            lca = np.float('nan') fireman        stats = {} fireman        start = time.time() fireman        # train_idx = task['split_names'].index('Train') fireman        # train_path = task['data_path'][train_idx] fireman        # train_dataset = _load_datasets([train_path])[0] fireman        train_dataset = _load_datasets(task, 'Train')[0] fireman        stats.update(self.finish_task(train_dataset, t_id, task_viz, fireman                                      path='drawings')) fireman        stats['duration'] = {'iterations': t, fireman                             'finish': time.time() - start, fireman                             'best_iterations': best_t} fireman        stats['params'] = {'total': self.n_params(t_id), fireman                           'new': self.new_params(t_id)} fireman        stats['lca'] = lca fireman        return stats fireman fireman    def get_trainable(self, use_ray_logging): fireman        if use_ray_logging: fireman            return TrainLLModel fireman        else: fireman            return OSTrainLLModel fireman# Abstract class representing Modular approaches. Contains all methods allowing fireman# to interact with a model as a combination of blocks. fireman# /!\ Only works with Vision models in the current implementation, supporting fireman# other modalities would require splitting this class to remove all of the CV fireman# specific stuff. firemanimport abc firemanfrom functools import partial fireman firemanfrom torch import nn firemanimport numpy as np fireman firemanfrom src.models.base import get_block_model firemanfrom src.models.utils import get_conv_out_size fireman fireman firemanclass ModularModel(nn.Module, abc.ABC): fireman    def __init__(self, n_hidden, n_convs, hidden_size, dropout_p, fireman                 channel_scaling, base_model=get_block_model, *args, **kwargs): fireman        super().__init__(*args, **kwargs) fireman        assert isinstance(hidden_size, list) fireman        if n_hidden is not None: fireman            assert len(hidden_size) == 1 fireman            hidden_size = hidden_size * n_hidden fireman        else: fireman            assert n_hidden is None fireman        self.hidden_size = hidden_size fireman        self.channel_scaling = channel_scaling fireman fireman        if isinstance(dropout_p, int): fireman            dropout_p = [dropout_p] * len(self.hidden_size) fireman        self._dropout_p = dropout_p fireman fireman        # self.n_hidden = n_hidden fireman        self.n_convs = n_convs fireman        self.base_model_func = partial(base_model, fireman                                       dropout_p=dropout_p, fireman                                       n_convs=self.n_convs) fireman fireman    def get_k(self, layer): fireman        if layer >= self.n_convs: fireman            return None fireman        elif isinstance(self._k, (tuple, list)): fireman            return self._k[layer] fireman        else: fireman            return self._k fireman fireman    def get_stride(self, layer): fireman        if layer >= self.n_convs: fireman            return None fireman        elif isinstance(self._stride, (tuple, list)): fireman            return self._stride[layer] fireman        else: fireman            return self._stride fireman fireman    def get_pad(self, layer): fireman        if layer >= self.n_convs: fireman            return None fireman        elif isinstance(self._pad, (tuple, list)): fireman            return self._pad[layer] fireman        else: fireman            return self._pad fireman fireman    def get_dropout_p(self, layer): fireman        if isinstance(self._dropout_p, (tuple, list)): fireman            return self._dropout_p[layer] fireman        else: fireman            return self._dropout_p fireman fireman    def get_pool_k(self, layer): fireman        if layer >= self.n_convs: fireman            return None fireman        if isinstance(self._pool_k, (tuple, list)): fireman            return self._pool_k[layer] fireman        else: fireman            return self._pool_k fireman fireman    def get_sizes(self, x_dim, n_classes): fireman        if len(x_dim) == 1: fireman            x_dim = x_dim[0] fireman            assert self.n_convs == 0, 'Can't use convs on 1D inputs.' fireman        assert len(n_classes) == 1, 'Only supports single output' fireman        n_classes = n_classes[0] fireman fireman        # Put all dimensions together for current model. fireman        model_dims = [x_dim, *self.hidden_size, n_classes] fireman        # if self.residual: fireman        #     return model_dims fireman fireman        for i in range(self.n_convs): fireman            # Compute intermediate map sizes fireman            img_size = model_dims[i][1:] fireman            k = self.get_k(i) fireman            pad = self.get_pad(i) fireman            stride = self.get_stride(i) fireman            out_size = get_conv_out_size(img_size, k, pad, stride) fireman            pool_k = self.get_pool_k(i) fireman            if pool_k is not None: fireman                out_size = get_conv_out_size(out_size, pool_k, 0, pool_k) fireman            model_dims[i + 1] = [model_dims[i + 1], *out_size] fireman        return model_dims fireman fireman    def get_res_sizes(self, x_dim, n_classes): fireman        if len(x_dim) == 1: fireman            x_dim = x_dim[0] fireman            assert self.n_convs == 0, 'Can't use convs on 1D inputs.' fireman        assert len(n_classes) == 1, 'Only supports single output' fireman        n_classes = n_classes[0] fireman fireman        # Put all dimensions together for current model. fireman        model_dims = [x_dim, *self._res_hidden_size, n_classes] fireman        # if self.residual: fireman        #     return model_dims fireman fireman        for i in range(self.n_res_blocks + 1): fireman            # Compute intermediate map sizes fireman            img_size = model_dims[i][1:] fireman            k = self._k fireman            pad = self._pad fireman            stride = self._res_stride[i] fireman            out_size = get_conv_out_size(img_size, k, pad, stride) fireman            pool_k = self._res_pool_k[i] fireman            if pool_k is not None: fireman                out_size = get_conv_out_size(out_size, pool_k, 0, pool_k) fireman            model_dims[i + 1] = [model_dims[i + 1], *out_size] fireman        return np.array(model_dims) firemanimport logging firemanfrom collections import OrderedDict firemanfrom functools import partial firemanfrom operator import itemgetter firemanfrom pathlib import Path fireman firemanimport networkx as nx firemanimport torch firemanimport torch.nn as nn fireman firemanfrom src.models.change_layer_llmodel import FrozenSequential firemanfrom src.models.utils import is_dummy_block, execute_step, graph_arch_details firemanfrom src.train.training import get_classic_dataloaders, train firemanfrom src.train.utils import _load_datasets firemanfrom src.utils.misc import pad_seq fireman firemanlogger = logging.getLogger(__name__) fireman fireman firemanclass ExhaustiveSearch(nn.Module): fireman    def __init__(self, graph, tunable_modules, frozen_modules, fireman                 stochastic_nodes, in_node, out_node, max_new_blocks): fireman        super(ExhaustiveSearch, self).__init__() fireman        self.tunable_modules = nn.ModuleList(tunable_modules) fireman        self.tunable_modules.requires_grad_(True) fireman        self.frozen_modules = nn.ModuleList(frozen_modules) fireman        self.frozen_modules.requires_grad_(False) fireman        self.stochastic_nodes = stochastic_nodes fireman        self.graph = graph fireman        self.in_node = in_node fireman        self.out_node = out_node fireman        self.models = nn.ModuleList() fireman        self.models_idx = {} fireman        self.res = {} fireman fireman        self.max_new_blocks = max_new_blocks fireman fireman    def init_models(self): fireman        archs = list(nx.all_simple_paths(self.graph, self.in_node, fireman                                         self.out_node)) fireman        for path in archs: fireman            new_model = FrozenSequential() fireman            last = None fireman            i = 0 fireman            n_new_blocks = 0 fireman            for node in path: fireman                assert node == self.in_node \ fireman                       or node in self.graph.successors(last) fireman                nn_module = self.graph.nodes[node]['module'] fireman                last = node fireman                if is_dummy_block(nn_module): fireman                    continue fireman                new_model.add_module(str(i), nn_module) fireman                if nn_module in self.frozen_modules: fireman                    new_model.frozen_modules_idx.append(i) fireman                else: fireman                    n_new_blocks += 1 fireman                    # else: fireman                    #     nn_module.load_state_dict(self.block_inits[node]) fireman                i += 1 fireman fireman            if n_new_blocks > self.max_new_blocks and len(archs) > 1: fireman                # print('Skipping {}'.format(path)) fireman                continue fireman            # print('Adding {}'.format(path)) fireman            new_model.n_out = self.n_out fireman            self.models_idx[tuple(path)] = len(self.models_idx) fireman            self.models.append(new_model) fireman fireman    def get_weights(self): fireman        weights = torch.tensor([1. if n in self._selected_path() else 0. fireman                                for n in self.stochastic_nodes]) fireman        return weights fireman fireman    def _selected_path(self): fireman        assert self.res fireman        all_res = map(lambda x: (x[1][2]['value'], x[0]), self.res.items()) fireman        return max(all_res, key=itemgetter(0))[1] fireman        # return next(iter(self.res.keys())) fireman fireman    def get_stoch_nodes(self): fireman        return self.stochastic_nodes fireman fireman    def get_graph(self): fireman        return self.graph fireman fireman    def nodes_to_prune(self, *args): fireman        return [n for n in self.stochastic_nodes fireman                if n not in self._selected_path()] fireman fireman    # def parameters(self): fireman    #     if len(self.models) == 0: fireman    #         self.init_models(