elf.res.items())) fireman        best_path = max(all_res, key=itemgetter(0))[1] fireman        _, best_metrics, best_chkpt = self.res[best_path] fireman        total_t = 0 fireman        cum_best_iter = 0 fireman fireman        splits = ['Trainer', 'Train', 'Val', 'Test'] fireman        metrics = ['accuracy_0'] fireman fireman        all_xs = [] fireman        best_accs = list(self.res[best_path][1]['Val accuracy_0'].values()) fireman fireman        for i, (path, (t, logs, best)) in enumerate(self.res.items()): fireman            total_t += t fireman            cum_best_iter += best['iter'] fireman            for m in metrics: fireman                for s in splits: fireman                    best_metrics[f'{s} {i} {m}_all'] = logs[f'{s} {m}'] fireman                    if s == 'Val': fireman                        all_xs.append(list(logs[f'{s} {m}'].keys())) fireman        # print() fireman        max_len = max(map(len, all_xs)) fireman        # print(all_xs) fireman        all_xs = [pad_seq(xs, max_len, xs[-1]) for xs in all_xs] fireman        # print(all_xs) fireman        # print(best_accs) fireman        # print(list(zip(*all_xs))) fireman        # print(list(zip_longest(*all_xs, fillvalue=0))) fireman        scaled_xs = [sum(steps) for steps in zip(*all_xs)] fireman        scaled_ys = pad_seq(best_accs, len(scaled_xs), best_accs[-1]) fireman        new_metric = dict(zip(scaled_xs, scaled_ys)) fireman        # print(new_metric) fireman        # print() fireman        best_metrics['Val accuracy_0_rescaled'] = new_metric fireman                # best_metrics[f'Val {m}_scales'] = logs[f'{s} {m}'] fireman fireman        self.models[self.models_idx[best_path]].load_state_dict(best_chkpt['state_dict']) fireman        best_chkpt['cum_best_iter'] = cum_best_iter fireman        return total_t, best_metrics, best_chkpt fireman fireman    def forward(self, input): fireman        if not self.models: fireman            self.init_models() fireman        # Assert that we are at test time fireman        assert len(self.models) == 1, len(self.models) fireman        return self.models[0](input) fireman fireman    def get_frozen_model(self): fireman        if not self.models: fireman            self.init_models() fireman        assert len(self.models) == 1, len(self.models) fireman        return self.models[0] fireman fireman    def get_top_archs(self, n=1): fireman        res = list(map(lambda x: (x[0], x[1][2]['value']), self.res.items())) fireman        res = sorted(res, key=itemgetter(1), reverse=True) fireman        return OrderedDict(res[:n]) fireman fireman    def arch_repr(self): fireman        return graph_arch_details(self.graph) fireman fireman firemandef wrap(*args, idx=None, uid=None, optim_fact, datasets_p, b_sizes, **kwargs): fireman    model = kwargs['model'] fireman    optim = optim_fact(model=model) fireman    datasets = _load_datasets(**datasets_p) fireman    train_loader, eval_loaders = get_classic_dataloaders(datasets, b_sizes, 0) fireman    if hasattr(model, 'train_loader_wrapper'): fireman        train_loader = model.train_loader_wrapper(train_loader) fireman fireman    res = train(*args, train_loader=train_loader, eval_loaders=eval_loaders, fireman                optimizer=optim, **kwargs) fireman    # logger.warning('{}=Received option {} results'.format(uid, idx)) fireman    return res firemanimport logging firemanimport os firemanfrom collections import defaultdict firemanfrom operator import itemgetter fireman firemanimport networkx as nx firemanimport numpy as np firemanimport torch firemanimport torch.nn as nn firemanfrom sklearn.neighbors import KNeighborsClassifier fireman firemanfrom src.models.ExhaustiveSearch import ExhaustiveSearch firemanfrom src.models.SPNN import SPNN firemanfrom src.models.change_layer_llmodel import _lin_block, _conv_block firemanfrom src.models.ll_model import LifelongLearningModel firemanfrom src.models.modular_model import ModularModel firemanfrom src.models.resnet import _make_layer, BasicBlock firemanfrom src.models.ssn_wrapper import SSNWrapper firemanfrom src.models.utils import _get_used_nodes, flatten firemanfrom src.utils.plotting import graph_to_svg, plot_svg firemanfrom supernets.interface.NetworkBlock import Add_Block, DummyBlock fireman firemanlogger = logging.getLogger(__name__) fireman fireman firemanclass ConstMult(nn.Module): fireman    def __init__(self, alpha=1.0): fireman        super().__init__() fireman        self.alpha = nn.Parameter(torch.Tensor(1)) fireman        nn.init.constant_(self.alpha, alpha) fireman fireman    def forward(self, x): fireman        return self.alpha * x fireman fireman firemandef get_aggreg_block(dropout_p, activation): fireman    mods = [Add_Block(activation)] fireman    if dropout_p is not None: fireman        mods.append(nn.Dropout(dropout_p)) fireman fireman    return nn.Sequential(*mods) fireman fireman firemanclass ZeroModel(nn.Module): fireman    def __init__(self, n_classes): fireman        super().__init__() fireman        self.n_classes = n_classes fireman fireman    def forward(self, x): fireman        return torch.zeros(x.size(0), self.n_classes).to(x.device) fireman fireman firemanclass MNTDP(LifelongLearningModel, ModularModel): fireman    IN_NODE = 'INs' fireman    # COL_IN_NODE = 'IN{}' fireman    OUT_NODE = 'OUT' fireman fireman    def __init__(self, deter_eval, use_adapters, residual, block_depth, fireman                 initial_p, stride, k, pool, pool_k, padding, pruning_treshold, fireman                 connections, store_graphs, learn_in_and_out, learn_all, fireman                 norm_layer, arch_sampler_type, split_training, single_stage, fireman                 strat, method='knn', block_id=None, n_neighbors=15, fireman                 max_new_blocks=float('inf'), arch_loss_coef=None, fireman                 n_source_models=-1, entropy_coef=None, *args, **kwargs): fireman        super(MNTDP, self).__init__(*args, **kwargs) fireman        self.columns = [] fireman fireman        self.column_repr_sizes = [] fireman        self.fixed_columns = set() fireman        self.fixed_graphs = [] fireman fireman        self.graph = nx.DiGraph() fireman        self.deter_eval = deter_eval fireman        self.pruning_treshold = pruning_treshold fireman        self.connections = connections fireman        assert store_graphs, 'All graphs should be stored' fireman        self.learn_in_and_out = learn_in_and_out fireman        self.learn_all = learn_all fireman        self.norm_layer = norm_layer fireman fireman        self.use_adapters = use_adapters fireman        self.residual = residual fireman        self.block_depth = block_depth fireman        self.initial_p = initial_p fireman fireman        self.max_new_blocks = max_new_blocks fireman        self.n_source_models = n_source_models fireman        self.n_neighbors = n_neighbors fireman fireman        self.pool = pool fireman fireman        if self.residual: fireman            n_layers = (self.n_convs - 1) * self.block_depth * 2 + 2 fireman            assert n_layers == 18 fireman            self.n_res_blocks = (self.n_convs - 1) * self.block_depth fireman            # if self.split_last: fireman            #     self.n_new_layers = self.block_depth - 1 fireman            #     self.n_convs += self.n_new_layers fireman            #     stride.extend([stride[-1]] * self.n_new_layers) fireman            assert k == 3, 'Resnet requires a kernel of size 3' fireman            self._k = k fireman            assert len(stride) == self.n_convs fireman            self._stride = stride fireman            self._res_stride = [stride[0]] fireman            for stride in stride[1:]: fireman                self._res_stride.append(stride) fireman                self._res_stride += [1] * (self.block_depth - 1) fireman            assert len(self._res_stride) == self.n_res_blocks + 1 fireman            self._res_stride.append(None) fireman            self._res_stride = np.array(self._res_stride) fireman fireman            self._pad = padding fireman            assert len(self.hidden_size) == 1, 'Resnet requires only 1 ' \ fireman                                               'hidden size, others are ' \ fireman                                               'computed using the first and' \ fireman                                               ' the stride' fireman            self._res_hidden_size = [self.hidden_size[0]] fireman            for i in range(1, self.n_convs): fireman                last_size = self.hidden_size[-1] fireman                if self.channel_scaling: fireman                    new_size = last_size * self.get_stride(i) fireman                    new_res_size = last_size * self._res_stride[i] fireman                else: fireman                    new_size = last_size fireman                    new_res_size = last_size fireman                self.hidden_size.append(new_size) fireman                self._res_hidden_size.extend([new_res_size]*self.block_depth) fireman            assert not self._dropout_p fireman            self._dropout_p = [None] * (self.n_res_blocks + 2) fireman            self._pool_k = [None] * (self.n_convs) fireman            self._res_pool_k = np.array([None] * (self.n_res_blocks + 2)) fireman            self._pool_k[-1] = pool_k fireman            self._res_pool_k[-2] = pool_k fireman fireman        else: fireman            if isinstance(stride, int): fireman                stride = [stride] * self.n_convs fireman            self._stride = stride fireman fireman            if isinstance(k, int): fireman                k = [k] * self.n_convs fireman            self._k = k fireman fireman            if isinstance(pool_k, int): fireman                pool_k = [pool_k] * self.n_convs fireman            self._pool_k = pool_k fireman fireman            if isinstance(padding, int): fireman                padding = [padding] * self.n_convs fireman            self._pad = padding fireman fireman        # self.graph.add_node(self.IN_NODE, module=DummyBlock()) fireman        # self.graph.add_node(self.OUT_NODE, module=Add_Block(False)) fireman fireman        if residual: fireman            if block_id is None: fireman                block_id = [0] fireman                for i in range(self.n_res_blocks): fireman                    resnet_block_ids = [i//self.block_depth+1] fireman                    block_id += resnet_block_ids fireman                block_id += [block_id[-1]+1] fireman            self.block_id = np.array(block_id) fireman            self.n_modules = self.block_id.max() + 1 fireman            assert len(self.block_id) == self.n_res_blocks + 2 fireman            assert 10 == len(self.block_id), "SHould be 10 for resnets" fireman        else: fireman            self.n_modules = len(self.hidden_size) + 1 fireman fireman        # if self.split_last: fireman        #     for i in range(len(self.block_id) - 2, len(block_id)): fireman        #         self.block_id[i] += 1 fireman fireman        self.arch_sampler_type = arch_sampler_type fireman        self.arch_samplers = [] fireman        self.search_res = [] fireman        self.knn_res = [] fireman        self.method = method fireman fireman        self.arch_loss_coef = arch_loss_coef fireman        self.entropy_coef = entropy_coef fireman        self.split_training = split_training fireman        self.single_stage = single_stage fireman        self.strat = strat fireman fireman        self.arch_scores = defaultdict(dict) fireman fireman    def get_candidate_models(self, task_id, descriptor, dataset, topk, fireman                             n_neighbors, max_samples=1000): fireman        if topk == -1: fireman            return list(range(task_id)) fireman        if torch.cuda.is_available(): fireman            device = 'cuda' fireman        else: fireman            device = 'cpu' fireman        train, val = dataset fireman        knn_perfs = [] fireman        model_perfs = [] fireman        rand_dists = [] fireman        for t_id in range(task_id): fireman            model = self.get_model(t_id) fireman            # model.freeze_arch() fireman            pruned_model = model.get_frozen_model() fireman            pruned_model.to(device) fireman fireman            features, model_preds, labels = [], [], [] fireman            with torch.no_grad(): fireman                n_samples = 0 fireman                for x, y in train: fireman                    x = x.to(device) fireman                    y = y.to(device) fireman                    feats, preds = pruned_model.feats_forward(x) fireman                    features.append(flatten(feats)) fireman                    model_preds.append(preds) fireman                    labels.append(y) fireman                    n_samples += x.size(0) fireman                    if n_samples >= max_samples: fireman                        break fireman                features = torch.cat(features, 0) fireman                model_preds = torch.cat(model_preds, 0) fireman                labels = torch.cat(labels, 0).flatten() fireman            n_neighbors = min(n_neighbors, features.size(0)) fireman            knn = KNeighborsClassifier(n_neighbors=n_neighbors) fireman            knn.fit(features.cpu(), labels.cpu()) fireman            preds, gt = [], [] fireman            with torch.no_grad(): fireman                n_samples = 0 fireman                for x, y in val: fireman                    x = x.to(device) fireman                    y = y.to(device) fireman                    feats, _ = pruned_model.feats_forward(x) fireman                    feats = flatten(feats).cpu() fireman                    preds.append(torch.tensor(knn.predict(feats))) fireman                    gt.append(y.flatten()) fireman                    n_samples += x.size(0) fireman                    if n_samples >= max_samples: fireman                        break fireman                preds = torch.cat(preds, 0).to(device) fireman                gt = torch.cat(gt, 0) fireman                # print(preds.shape, gt.shape) fireman                # print(torch.stack((preds, gt))) fireman                # print(preds) fireman                knn_perfs.append((preds == gt).float().mean().item()) fireman                # print(knn_perfs) fireman                acc = (model_preds.argmax(1) == labels).float().mean().item() fireman                model_perfs.append(acc) fireman                rand_dists.append(abs(1/model_preds.size(1) - acc)) fireman        self.arch_scores[task_id]['task id'] = list(range(task_id)) fireman        self.arch_scores[task_id]['knn'] = knn_perfs fireman        self.arch_scores[task_id]['accs'] = model_perfs fireman        self.arch_scores[task_id]['rand dist'] = rand_dists fireman        if not hasattr(self, 'method'): fireman            self.method = 'knn' fireman        if self.method == 'knn': fireman            arg_res = np.argsort(knn_perfs) fireman            self.knn_res.append({k: knn_perfs[k] for k in arg_res}) fireman        elif self.method == 'best-rand': fireman            arg_res = np.argsort(rand_dists) fireman            self.knn_res.append({k: rand_dists[k] for k in arg_res}) fireman        elif self.method == 'rand': fireman            arg_res = np.random.choice(task_id, task_id, replace=False) fireman            self.knn_res.append({k: knn_perfs[k] for k in arg_res}) fireman        else: fireman            raise ValueError(f'unknown method {self.method}') fireman        res = arg_res[-topk:].tolist() fireman        return res fireman fireman    def get_nodes_from_models(self, model_ids): fireman        nodes = set() fireman        for mod in model_ids: fireman            graph = self.fixed_graphs[mod] fireman            nodes.update(graph.nodes) fireman        return nodes fireman fireman    def get_backward_lateral_connections(self, col_id, targ_depth, fireman                                         candidate_nodes, is_last): fireman        """ fireman        Return the new connections for current depth: fireman        If current node is (2, 1), we will get all backward connections __for fireman        current depth__ (and not current node) i.e. the connections from fireman        (2, 0) to (0, 1) and from (2, 0) to (1, 1). fireman        We need additional check because we can still have bw modules in fireman        `self.columns` at position [col_id][targ_depth] even if the node fireman        (col_id, targ_depth) has already been removed. fireman        :param col_id: fireman        :param targ_depth: fireman        :param is_last: fireman        :return: fireman        """ fireman        assert len(self.columns) == col_id + 1 fireman        lateral_connections = {} fireman        if 'bw' not in self.connections or is_last: fireman            return lateral_connections fireman fireman        for targ_col_id, targ_col in enumerate(self.columns[:col_id]): fireman            # if targ_col_id not in candidate_nodes: fireman            #     continue fireman            targ_layer = targ_col.get(targ_depth) fireman            if targ_layer and (targ_col_id, targ_depth) in targ_layer\ fireman                and (targ_col_id, targ_depth) in candidate_nodes: fireman                repr_size = self.column_repr_sizes[targ_col_id][targ_depth] fireman                lateral_connections[targ_col_id] = repr_size fireman        return lateral_connections fireman fireman    def get_forward_lateral_connections(self, col_id, depth, candidate_nodes): fireman        assert len(self.columns) == col_id + 1 fireman        lateral_connections = {} fireman        if 'fw' not in self.connections or depth == 1: fireman            # This is the first "real" layer, forward connection would be fireman            # identical to the (col_id, depth, 'w') layer fireman            return lateral_connections fireman        for src_col_id, src_col in enumerate(self.columns[:col_id]): fireman            # if src_col_id not in columns: fireman            #     continue fireman            src_layer = src_col.get(depth - 1) fireman            if src_layer and (src_col_id, depth - 1) in src_layer and\ fireman                (src_col_id, depth-1) in candidate_nodes: fireman                repr_size = self.column_repr_sizes[src_col_id] fireman                repr_size = repr_size[depth - 1] \ fireman                    if len(repr_size) >= depth else -1 fireman                lateral_connections[src_col_id] = repr_size fireman        return lateral_connections fireman fireman    def add_column(self, sizes, candidate_nodes): fireman        new_col_id = len(self.columns) fireman        self.columns.append({}) fireman fireman        # Add input and first node fireman        in_nodes = self.connect_new_input(new_col_id, candidate_nodes) fireman        self.columns[new_col_id][self.IN_NODE] = in_nodes fireman fireman        in_size = sizes[0] fireman        # for depth, out_size in enumerate(sizes[1:], start=1): fireman        for depth in range(1, self.n_modules+1): fireman            # Start from 1 because input (depth 0) is already connected. fireman            # assert out_size == sizes[depth] fireman            out_size = sizes[depth] if depth < len(sizes) else None fireman            f_connections = \ fireman                self.get_forward_lateral_connections(new_col_id, depth, fireman                                                     candidate_nodes) fireman            is_last_layer = depth == self.n_modules fireman            backward_connections = \ fireman                self.get_backward_lateral_connections(new_col_id, depth, fireman                                                      candidate_nodes, fireman                                                      is_last_layer) fireman            out_activations = not is_last_layer fireman            new_modules = self.add_layer(f_connections, backward_connections, fireman                                         depth, new_col_id, out_activations, fireman                                         in_size, out_size) fireman            in_size = out_size fireman            self.columns[-1][depth] = new_modules fireman fireman        # Add output fireman        out_nodes = self.connect_new_output(new_col_id, candidate_nodes) fireman        self.columns[new_col_id][self.OUT_NODE] = out_nodes fireman fireman    def connect_new_output(self, col_id, candidate_nodes): fireman        new_out = (col_id, self.OUT_NODE) fireman        mod = Add_Block(False) fireman        self.graph.add_node(new_out, module=mod) fireman fireman        out_connections = {new_out: mod} fireman        for prev_col_id in range(col_id + 1): fireman            last_layer_depth = self.n_modules fireman            # last_layer_depth_old = len(self.hidden_size) + 1 fireman            src_layer = self.columns[prev_col_id].get(last_layer_depth) fireman            last_node = (prev_col_id, last_layer_depth) fireman            if not src_layer or last_node not in src_layer\ fireman                    or last_node not in \ fireman                    candidate_nodes | {(col_id, last_layer_depth)}: fireman                    # or prev_col_id not in (columns + [col_id]): fireman                continue fireman            if self.learn_in_and_out: fireman                conn_name = (col_id, self.OUT_NODE, prev_col_id) fireman                mod = DummyBlock() fireman                out_connections[conn_name] = mod fireman                self.graph.add_node(conn_name, module=mod) fireman                self.graph.add_edge(last_node, conn_name) fireman                self.graph.add_edge(conn_name, new_out) fireman            else: fireman                self.graph.add_edge(last_node, new_out) fireman        return out_connections fireman fireman    def connect_new_input(self, col_id, candidate_nodes): fireman        # new_input = self.COL_IN_NODE.format(col_id) fireman        new_input = (col_id, self.IN_NODE) fireman        # mod = InputBlock() fireman        mod = DummyBlock() fireman        self.graph.add_node(new_input, module=mod) fireman fireman        mod = DummyBlock() fireman        self.graph.add_node((col_id, 0), module=mod) fireman        self.columns[col_id][0] = {(col_id, 0): mod} fireman fireman        # input_connections = {new_input: mod} fireman        # real_in = (col_id, self.IN_NODE, self.REAL_IN_NODE) fireman        # rmod = DummyBlock() fireman        # self.graph.add_node(real_in, module=rmod) fireman        input_connections = {new_input: mod} fireman        for prev_col_id in range(col_id + 1): fireman            in_layer = self.columns[prev_col_id].get(0) fireman            target_node = (prev_col_id, 0) fireman            if not in_layer or target_node not in in_layer\ fireman                    or target_node not in candidate_nodes | {(col_id, 0)}: fireman                    # or prev_col_id not in columns + [col_id]: fireman                continue fireman fireman            if self.learn_in_and_out: fireman                conn_name = (col_id, self.IN_NODE, prev_col_id) fireman                mod = DummyBlock() fireman                input_connections[conn_name] = mod fireman                self.graph.add_node(conn_name, module=mod) fireman                self.graph.add_edge(new_input, conn_name) fireman                self.graph.add_edge(conn_name, target_node) fireman            else: fireman                self.graph.add_edge(new_input, target_node) fireman        return input_connections fireman fireman    def add_layer(self, f_connections, b_connections, depth, col_id, out_act, fireman                  in_size, out_size): fireman        """ Add a layer to the 'col_id' column fireman        :returns the modules created for this block fireman        """ fireman        # Create node corresponding to current depth and column id fireman        h_name = (col_id, depth) fireman        # h = Add_Block(activation=out_act) fireman        # drop_p = self.dropout_p[depth - 1] if out_act else None fireman        h = get_aggreg_block(None, out_act) fireman        self.graph.add_node(h_name, module=h) fireman fireman        # Create the connection from same column fireman        w_name = (col_id, depth, 'w') fireman        w = self.get_module(in_size, out_size, depth - 1) fireman        self.graph.add_node(w_name, module=w) fireman        if depth == 0: fireman            src_node = (col_id, self.IN_NODE) fireman        else: fireman            src_node = (col_id, depth - 1) fireman        self.graph.add_edge(src_node, w_name) fireman        self.graph.add_edge(w_name, h_name) fireman fireman        added_modules = {w_name: w, h_name: h} fireman fireman        # Create forward lateral connections fireman        u_name = (col_id, depth, 'u') fireman fireman        for source_column, size in f_connections.items(): fireman            if self.use_adapters: fireman                # Add the V module fireman                raise NotImplementedError('Need to figure out what to do with' fireman                                          ' pooling') fireman                mod = nn.Sequential(ConstMult(), fireman                                    self.get_module(size, in_size, depth - 1, fireman                                                    True), fireman                                    nn.ReLU()) fireman                lateral_out_node = u_name fireman            else: fireman                # Connect directly to the current col, depth out node fireman                mod = self.get_module(size, out_size, depth - 1) fireman                lateral_out_node = h_name fireman fireman            proj_name = (col_id, depth, source_column, 'f') fireman            source = (source_column, depth - 1) fireman            self.graph.add_node(proj_name, module=mod) fireman            self.graph.add_edge(source, proj_name) fireman            self.graph.add_edge(proj_name, lateral_out_node) fireman fireman            added_modules[proj_name] = mod fireman fireman        if f_connections and self.use_adapters: fireman            # Add the second layer of 