an    def remove_node(self, node): fireman        node_col = node[0] fireman        node_lay = node[1] fireman        logger.debug('Pruning {}'.format(node)) fireman        self.graph.remove_node(node) fireman        del self.columns[node_col][node_lay][node] fireman fireman        for i, arch_sampler in enumerate(self.arch_samplers[node_col:]): fireman            if node in arch_sampler.var_names: fireman                arch_sampler.remove_var(node) fireman            elif i == 0: fireman                is_aggreg_node = len(node) == 2 fireman                is_dummy_node = node[1] in (self.IN_NODE, self.OUT_NODE) fireman                assert is_aggreg_node or \ fireman                       not self.learn_in_and_out and is_dummy_node fireman fireman    def clean_graph(self): fireman        for i in range(len(self.columns)): fireman            # We clean the graph column by column fireman            used_nodes = self.get_used_nodes(i) fireman            for lay in self.columns[i].values(): fireman                for node in list(lay.keys()): fireman                    if node not in used_nodes: fireman                        self.remove_node(node) fireman fireman    def get_used_nodes(self, col): fireman        candidate_nodes = [] fireman        for column in self.columns[:col + 1]: fireman            for lay in column.values(): fireman                candidate_nodes.extend(lay.keys()) fireman fireman        input = (col, self.IN_NODE) fireman        last_node = (col, self.OUT_NODE) fireman fireman        return _get_used_nodes(self.graph, candidate_nodes, input, last_node) fireman fireman    def _new_model(self, **kwargs): fireman        raise NotImplementedError fireman fireman    def finish_task(self, dataset, task_id, viz=None, path=None): fireman        if task_id in self.fixed_columns: fireman            raise ValueError('Task {} is already finished'.format(task_id)) fireman        assert set(range(task_id)) == self.fixed_columns fireman        self.fixed_co