'.join(map(str, sorted(all_res, key=itemgetter(0), fireman                                             reverse=True))) fireman            viz.text('<pre>{}</pre>'.format(pres)) fireman        return additional_results fireman fireman    def set_h_params(self, arch_loss_coef, entropy_coef, split_training): fireman        self.arch_loss_coef = arch_loss_coef fireman        self.entropy_coef = entropy_coef fireman        self.split_training = split_training fireman fireman fireman firemandef clean_graph(g, in_node, out_node): fireman    # candidate_nodes = list(g.nodes) fireman    # for column in self.columns[:col+1]: fireman    #     for lay in column.values(): fireman    #         candidate_nodes.extend(lay.keys()) fireman    # input = (col, self.IN_NODE) fireman    # if in_node not in candidate_nodes: fireman    #     return set() fireman    # input = self.COL_IN_NODE.format(col) fireman    # candidate_nodes.append(self.IN_NODE) fireman fireman    # candidate_nodes.append(input) fireman fireman    # last_node = (col, len(self.hidden_size)+1) fireman    used_nodes = set() fireman    for path in nx.all_simple_paths(g, in_node, out_node): fireman        used_nodes.update(path) fireman fireman    nodes_to_remove = set(g.nodes) - used_nodes fireman    # for node in list(g.nodes): fireman    #     if node not in used_nodes: fireman    #         g.remove_node(node) fireman    return nodes_to_remove firemanimport copy fireman firemanimport torch firemanimport torch.nn as nn fireman firemanfrom src.models.change_layer_llmodel import FrozenSequential firemanfrom src.models.utils import is_dummy_block, _get_used_nodes firemanfrom supernets.networks.StochasticSuperNetwork import StochasticSuperNetwork fireman fireman firemanclass SPNN(StochasticSuperNetwork): fireman    # IN_NODE = 'IN' fireman    # OUT_NODE = 'OUT' fireman fireman    def __init__(self, graph, tunable_modules, frozen_modules, fireman                 stochastic_nodes, in_node, out_node, single_stage): fireman        super(SPNN, self).__init__() fireman        self.tunable_modules = nn.ModuleList(tunable_modules) fireman        self.tunable_modules.requires_grad_(True) fireman        self.frozen_modules = nn.ModuleList(frozen_modules) fireman        self.frozen_modules.requires_grad_(False) fireman        self.graph = graph fireman fireman        self.single_stage = single_stage fireman        self.block_inits = {} fireman        nodes_to_raise = [] fireman        for node in graph.nodes: fireman            mod = graph.nodes[node]['module'] fireman            if not (self.single_stage or mod in frozen_modules): fireman                self.block_inits[node] = copy.deepcopy(mod.state_dict()) fireman            if node in stochastic_nodes: fireman                if node not in graph: fireman                    nodes_to_raise.append(node) fireman                self.register_stochastic_node(node) fireman fireman        if nodes_to_raise: fireman            raise ValueError('Nodes to register not ' fireman                             'in graph {}'.format(nodes_to_raise)) fireman fireman        self.set_graph(self.graph, [in_node], [out_node]) fireman fireman    def forward(self, inputs): fireman        return super(SPNN, self).forward(inputs)[0] fireman fireman    def train(self, mode=True): fireman        super().train(mode) fireman        self.frozen_modules.train(False) fireman        return self fireman fireman    def get_pruned_model(self, weights): fireman        assert weights.ndim == 1 fireman        # print(weights) fireman        assert torch.equal(weights, weights ** 2) fireman        candidates = set() fireman        for node in self.graph.nodes: fireman            if node not in self.stochastic_node_ids: fireman                candidates.add(node) fireman            else: fireman                idx = self.stochastic_node_ids[node] fireman                if weights[idx] == 1: fireman                    candidates.add(node) fireman        used_nodes = _get_used_nodes(self.graph, candidates, fireman                                     self.in_nodes[0], self.out_nodes[0]) fireman fireman        new_model = FrozenSequential() fireman        last = None fireman        i = 0 fireman        for node in self.traversal_order: fireman            if node not in used_nodes: fireman                continue fireman            assert node == self.in_nodes[0] \ fireman                   or node in self.graph.successors(last) fireman            nn_module = self.graph.nodes[node]['module'] fireman            last = node fireman            if is_dummy_block(nn_module): fireman                continue fireman            new_model.add_module(str(i), nn_module) fireman            if nn_module in self.frozen_modules: fireman                new_model.frozen_modules_idx.append(i) fireman                # else: fireman                #     nn_module.load_state_dict(self.block_inits[node]) fireman            i += 1 fireman        return new_model fireman# Copyright (c) Facebook, Inc. and its affiliates. fireman# fireman# This source code is licensed under the MIT license found in the fireman# LICENSE file in the root directory of this source tree. firemanimport logging firemanfrom collections import OrderedDict firemanfrom operator import itemgetter fireman firemanimport networkx as nx firemanimport torch firemanfrom torch import nn firemanfrom torch.utils.data import DataLoader fireman firemanfrom src.models.samplers.arch_sampler import ArchSampler firemanfrom src.models.samplers.conditional_softmax_sampler import \ fireman    CondiSoftmaxArchGenerator firemanfrom src.models.samplers.softmax_sampler import SoftmaxArchGenerator firemanfrom src.models.samplers.static_sampler import StaticArchGenerator firemanfrom src.models.utils import graph_arch_details firemanfrom src.train.utils import strat_split_from_y, RoundRobinDataloader fireman firemanlogger = logging.getLogger(__name__) fireman fireman firemanclass SSNWrapper(nn.Module): fireman    _SAMPLERS = dict(static=StaticArchGenerator, fireman                     layer_softmax=SoftmaxArchGenerator, fireman                     node_softmax=SoftmaxArchGenerator, fireman                     conditional_softmax=CondiSoftmaxArchGenerator) fireman fireman    def __init__(self, ssn_model, initial_p, deter_eval, arch_loss_coef, fireman                 entropy_coef, split_training, t_id, all_same=False, fireman                 arch_sampler=None): fireman        super().__init__() fireman        self.ssn = ssn_model fireman        self.weight_mask = torch.zeros(len(self.ssn.stochastic_node_ids)) fireman        for node, pos in self.ssn.stochastic_node_ids.items(): fireman            if node[0] == t_id: fireman                # print('OUIOUIOUI ', node) fireman                self.weight_mask[pos] = 1 fireman            # else: fireman            #     print('NONNONNON', node) fireman fireman        # self.distrib_gen = ConstantDistribGenerator(n_vars, p=0.7) fireman fireman fireman        self.all_same = all_same fireman        self.initial_p = initial_p fireman fireman        self.arch_cost_coef = arch_loss_coef fireman        self.entropy_coef = entropy_coef fireman fireman        self.split_training = split_training fireman        self.cur_split = None fireman        self.frozen_arch = False fireman        # frozen model is a list to prevent it from appearing in the state_dict fireman        self.frozen_model = [] fireman        self.t_id = t_id fireman fireman        if isinstance(arch_sampler, str): fireman            self.arch_sampler = self.get_distrib_gen(deter_eval, fireman                                                     arch_sampler) fireman        elif isinstance(arch_sampler, ArchSampler): fireman            self.arch_sampler = arch_sampler fireman        else: fireman            raise ValueError('Unknown arch sampler type: {}' fireman                             .format(type(arch_sampler))) fireman        weights = self.arch_sampler().squeeze() fireman        # model.arch_sampler.freeze() fireman        nodes = list(self.ssn.stochastic_node_ids.keys()) fireman        assert len(nodes) == weights.size(0) and weights.dim() == 1 fireman fireman    def get_distrib_gen(self, deter_eval, arch_sampler): fireman        n_vars = self.ssn.n_sampling_params fireman        if n_vars == 0: fireman            logger.warning('No sotchastic nodes are detected.') fireman            # logger.warning(f'Replacing {arch_sampler} with static sampler') fireman            # arch_sampler = 'static' fireman        var_names = list(self.ssn.stochastic_node_ids.keys()) fireman fireman        if arch_sampler == 'layer_softmax': fireman            groups = [name[1] for name in var_names] fireman        elif arch_sampler in ['node_softmax', 'conditional_softmax']: fireman            groups = [] fireman            for var in var_names: fireman                preds = list(self.ssn.graph.predecessors(var)) fireman                assert len(preds) == 1 fireman                groups.append(preds[0]) fireman        else: fireman            groups = None fireman fireman        samp_cls = self._SAMPLERS[arch_sampler] fireman        return samp_cls(distrib_dim=n_vars, fireman                        initial_p=self.initial_p, fireman                        groups=groups, fireman                        deter_eval=deter_eval, fireman                        all_same=self.all_same, fireman                        var_names=var_names, fireman                        graph=self.ssn.graph) fireman fireman    def forward(self, inputs, splits=None): fireman        if splits is None: fireman            assert not (self.split_training and self.training) or \ fireman                   self.arch_sampler.is_deterministic() fireman            self.cur_split = None fireman        elif self.frozen_arch: fireman            self.cur_split = 0 fireman        else: fireman            self.cur_split = splits.unique().item() fireman        if self.cur_split == 0: fireman            self.arch_sampler.eval() fireman        elif self.cur_split == 1: fireman            self.ssn.eval() fireman fireman        if self.frozen_arch: fireman            return self.frozen_model[0](inputs) fireman fireman        self.arch_sampler.start_new_sequence() fireman        arch_probas = self.arch_sampler() fireman fireman        # Case of multiple input nodes where input is a list: fireman fireman        b_size = inputs[0].size(0) if isinstance(inputs, list) \ fireman            else inputs.size(0) fireman        arch_samplings = self.arch_sampler.sample_archs(b_size, arch_probas) fireman        self.ssn.samplings = arch_samplings fireman fireman        # self.ssn.start_new_sequence() fireman        # self.ssn.set_probas() fireman        # print('Arch_ent: {} ({}), Train={}, split={}'.format(self.arch_sampler.distrib_entropies[0].mean(), fireman        #                                            self.frozen_arch, fireman        #                                            self.training, fireman        #                                            self.cur_split)) fireman        # self.check_arch_freezing() fireman        return self.ssn(inputs) fireman fireman    def check_arch_freezing(self, *args, ent=None, epoch=None): fireman        # print('called with epoch={}'.format(epoch)) fireman        if ent is None: fireman            ent = self.arch_sampler.distrib_entropies[0].mean() fireman            # print('CALLED WITHOUT ENT') fireman        else: fireman            ent = ent fireman            # print('CALLED WITH ENT') fireman        # print('ENT={}, weights={}'.format(ent, weights)) fireman        if ent < 0.001 or epoch > 0.5: fireman            self.freeze_arch() fireman fireman    def get_frozen_model(self): fireman        if not self.frozen_arch: fireman            self.freeze_arch() fireman        return self.frozen_model[0] fireman fireman    def freeze_arch(self): fireman        # print('FREEEEEZE') fireman        if self.frozen_arch: fireman            return fireman        self.frozen_arch = True fireman        weights = self.arch_sampler() fireman        arch_samplings = self.arch_sampler.sample_archs(1, weights).squeeze() fireman fireman        self.frozen_model.append(self.ssn.get_pruned_model(arch_samplings)) fireman fireman    def requires_grad(self): fireman        if self.frozen_arch: fireman            req = self.frozen_model[0].requires_grad() fireman            # print('REQ:{}'.format(req)) fireman            return req fireman        return True fireman fireman    def loss_wrapper(self, loss_fn): fireman        def loss(*args, **kwargs): fireman            task_loss = loss_fn(*args, **kwargs) fireman            reward = -task_loss.detach() fireman            # samp = self.ssn.samplings fireman            # samp_size = samp.size() fireman            # a = self.weight_mask fireman            # print(samp_size) fireman            # print(a) fireman fireman            # if self.frozen_arch: fireman            if self.frozen_arch or len(self.arch_sampler.log_probas) == 0: fireman                arch_loss = torch.zeros(1).to(task_loss.device) fireman                entropy_loss = torch.zeros(1).to(task_loss.device) fireman            else: fireman                arch_costs = self.ssn.samplings * self.weight_mask.to(self.ssn.samplings.device) fireman                arch_costs = arch_costs.sum(-1) fireman                reward -= self.arch_cost_coef * arch_costs fireman                reward -= reward.mean() fireman                log_p = self.arch_sampler.log_probas fireman                assert len(log_p) == 1 fireman                log_p = log_p[0] fireman                assert task_loss.dim() == 1 fireman                assert task_loss.size(0) == log_p.size(0) or log_p.size(0) == 1 fireman                arch_loss = -(reward.unsqueeze(-1) * log_p).mean(1) fireman                assert arch_loss.dim() == 1 fireman fireman                entropy_loss = -self.entropy_coef * self.arch_sampler.entropy().mean() fireman            # ent_1 = self.arch_sampler.entropy() fireman            # ent_2 = [e.size() for e in self.arch_sampler.distrib_entropies] fireman            # ent_3 = [e.mean() for e in self.arch_sampler.distrib_entropies] fireman            # print(ent_1) fireman            # print(ent_2) fireman            # print(ent_3) fireman            # print() fireman            # if self.cur_split is None: fireman            losses = {'task all_loss': task_loss, fireman                      'arch all_loss': arch_loss, fireman                      'entropy all_loss': entropy_loss} fireman            return sum(losses.values()), losses fireman            # elif self.cur_split == 0:  # and self.t_id == 0: fireman            #     return task_loss fireman            # else: fireman            #     return arch_loss + entropy_loss fireman fireman        return loss fireman fireman    @property fireman    def in_node(self): fireman        return self.ssn.in_nodes[0] fireman fireman    @property fireman    def out_node(self): fireman        return self.ssn.out_nodes[0] fireman fireman    def nodes_to_prune(self, *args, **kwargs): fireman        return self.arch_sampler.nodes_to_prune(*args, **kwargs) fireman fireman    def get_weights(self): fireman        return self.arch_sampler().squeeze() fireman fireman    def get_stoch_nodes(self): fireman        return list(self.ssn.stochastic_node_ids.keys()) fireman fireman    def get_graph(self): fireman        return self.ssn.graph fireman fireman    def sampled_entropy(self): fireman        if self.frozen_arch or len(self.arch_sampler.distrib_entropies) == 0: fireman            return torch.zeros(1) fireman        else: fireman            assert len(self.arch_sampler.distrib_entropies) == 1 fireman            return self.arch_sampler.distrib_entropies[0].mean() fireman fireman    def global_entropy(self): fireman        return self.arch_sampler.entropy().mean() fireman fireman    def train_loader_wrapper(self, train_loader): fireman        if not self.split_training or self.arch_sampler.is_deterministic(): fireman            return train_loader fireman fireman        ds = train_loader.dataset fireman        splits = strat_split_from_y(ds) fireman fireman        new_loaders = [DataLoader(split, train_loader.batch_size, shuffle=True, fireman                                  num_workers=train_loader.num_workers) fireman                        for split in splits] fireman fireman        return RoundRobinDataloader(new_loaders) fireman fireman    def param_groups(self, *args, **kwargs): fireman        return [ fireman            {'params': self.ssn.parameters(*args, **kwargs)}, fireman            {'params': self.arch_sampler.parameters(*args, **kwargs)} fireman        ] fireman fireman    def set_h_params(self, arch_loss_coef, entropy_coef, split_training): fireman        self.arch_cost_coef = arch_loss_coef fireman        self.entropy_coef = entropy_coef fireman        self.split_training = split_training fireman fireman    def get_top_archs(self, n=1): fireman        weights = self.get_weights() fireman        res = [] fireman        for path in nx.all_simple_paths(self.ssn.graph, self.ssn.in_nodes[0], fireman                                        self.ssn.out_nodes[0]): fireman            p = 1 fireman            for node in path: fireman                if node in self.ssn.stochastic_node_ids: fireman                    p *= weights[self.ssn.stochastic_node_ids[node]] fireman            res.append((tuple(path), p.item())) fireman        res = sorted(res, key=itemgetter(1), reverse=True) fireman        return OrderedDict(res[:n]) fireman fireman    def arch_repr(self): fireman        return graph_arch_details(self.ssn.graph) firemanimport torch firemanfrom torch import nn fireman fireman firemanclass ArchSampler(nn.Module): fireman    def __init__(self, distrib_dim, all_same, deter_eval, var_names=None, fireman                 *args, **kwargs): fireman        super().__init__() fireman        self.distrib_dim = distrib_dim fireman fireman        self.all_same = all_same fireman        self.deter_eval = deter_eval fireman        self.frozen = False fireman        self.log_probas = None fireman        self.distrib_entropies = None fireman        self._seq_probas = None fireman fireman        if var_names is not None: fireman            assert len(var_names) == self.distrib_dim fireman        self.var_names = var_names fireman fireman    def freeze(self): fireman        self.frozen = True fireman fireman    def start_new_sequence(self): fireman        self.log_probas = [] fireman        self.distrib_entropies = [] fireman        self._seq_probas = [] fireman fireman    def nodes_to_prune(self, treshold): fireman        nodes = [] fireman        for node, weight in zip(self.var_names, self().squeeze().unbind()): fireman            if weight < treshold: fireman                nodes.append(node) fireman        return nodes fireman fireman    def sample_archs(self, batch_size, probas): fireman        """ fireman        Hook called by pytorch before each forward fireman        :param: Current module fireman        :param input: Input given to the module's forward fireman        :return: fireman        """ fireman        self._check_probas(probas, self.all_same) fireman fireman        # Check the compatibility with the batch_size fireman        if probas.size(0) != batch_size: fireman            if probas.size(0) != 1: fireman                raise ValueError('Sampling probabilities dimensions {} ' fireman                                 'doesn't match with batch size {}.' fireman                                 .format(probas.size(), batch_size)) fireman            if not self.all_same: fireman                probas = probas.expand(batch_size, -1) fireman fireman        distrib = torch.distributions.Bernoulli(probas) fireman        if not self.training and self.deter_eval: fireman            samplings = (probas > 0.5).float() fireman        else: fireman            samplings = distrib.sample() fireman fireman        if self.all_same: fireman            samplings = samplings.expand(batch_size, -1) fireman fireman        self._seq_probas.append(probas) fireman        self.distrib_entropies.append(distrib.entropy()) fireman        self.log_probas.append(distrib.log_prob(samplings)) fireman        return samplings fireman fireman    def _check_probas(self, probas, all_same): fireman        """ fireman        :param probas: B_size*N_nodes Tensor containing the probability of each fireman         arch being sampled in the nex forward. fireman        :param all_same: if True, the same sampling will be used for the whole fireman        batch in the next forward. fireman        :return: fireman        """ fireman        if probas.dim() != 2 or all_same and probas.size(0) != 1: fireman            raise ValueError( fireman                'probas params has wrong dimension: {} (all_same={})'.format( fireman                    probas.size(), all_same)) fireman fireman        if probas.size(-1) != self.distrib_dim: fireman            raise ValueError('Should have exactly as many probas as the ' fireman                             'number of stochastic nodes({}), got {} instead.' fireman                             .format(self.distrib_dim, probas.size(-1))) fireman fireman    @property fireman    def last_arch_probas(self): fireman        return self.probas fireman fireman    @property fireman    def last_sequence_probas(self): fireman        """ fireman        :return: The probabilities of each arch for the last sequence in fireman        format (seq_len*batch_size*n_sampling_params) fireman        """ fireman        return torch.stack(self._seq_probas) firemanfrom collections import defaultdict fireman firemanimport torch firemanimport torch.nn.functional as f firemanfrom torch import nn firemanfrom torch.distributions import Categorical fireman firemanfrom src.models.samplers.arch_sampler import ArchSampler fireman fireman firemanclass SoftmaxArchGenerator(ArchSampler): fireman    def __init__(self, groups, graph, *args, **kwargs): fireman        super().__init__(*args, **kwargs) fireman        self.groups = groups fireman        id_gen = defaultdict() fireman        id_gen.default_factory = id_gen.__len__ fireman        group_ids = torch.tensor([id_gen[grp] for grp in groups]) fireman        self.group_ids_index = dict(id_gen.items())  # Freeze the id generator fireman fireman        self.distrib_groups = group_ids fireman        self.graph = graph fireman fireman        self.group_ids = self.distrib_groups.unique() fireman        self.group_masks = [self.distrib_groups.eq(id) fireman                            for id in self.group_ids] fireman        self.group_var_names = [[] for _ in range(self.group_ids.numel())] fireman        for grp, var in zip(self.distrib_groups.unbind(), self.var_names): fireman            self.group_var_names[grp.item()].append(var) fireman        self.group_sizes = [mask.sum().item() for mask in self.group_masks] fireman fireman        self.params = [nn.Parameter(torch.zeros(size)) fireman                       for size in self.group_sizes] fireman fireman        self.params = nn.ParameterList(self.params) fireman fireman    def forward(self, z=None): fireman        return self.get_distrib() fireman fireman    def entropy(self): fireman        entropies = [Categorical(p.softmax(0)).entropy() for p in self.params] fireman        # if self.training: fireman        #     print('Training mode') fireman fireman        return torch.stack(entropies).mean() if entropies else torch.Tensor() fireman fireman    def remove_var(self, name): fireman        assert self.var_names fireman        self.distrib_dim -= 1 fireman        remove_idx = self.var_names.index(name) fireman        grp_idx = self.distrib_groups[remove_idx] fireman        idx_in_group = self.group_masks[grp_idx][:remove_idx].sum().item() fireman        self.var_names.remove(name) fireman fireman        self.group_var_names[grp_idx].remove(name) fireman fireman        all_idx_mask = torch.ones_like(self.distrib_groups).bool() fireman        all_idx_mask[remove_idx] = 0 fireman        self.distrib_groups = self.distrib_groups[all_idx_mask] fireman        self.group_masks = [m[all_idx_mask] for m in self.group_masks] fireman fireman        param = self.params[grp_idx] fireman        group_idx_mask = torch.ones_like(param).bool() fireman        group_idx_mask[idx_in_group] = 0 fireman        self.params[grp_idx] = nn.Parameter(param[group_idx_mask]) fireman fireman        self.group_sizes[grp_idx] -= 1 fireman fireman    def get_distrib(self): fireman        device = self.params[0].device if self.params else 'cpu' fireman        distrib = torch.zeros(self.distrib_dim).to(device) fireman        for p, mask in zip(self.params, self.group_masks): fireman            mask = mask.to(device) fireman            distrib[mask] = p.softmax(0) fireman fireman        return distrib.unsqueeze(0) fireman fireman    def is_deterministic(self): fireman        distrib = self.get_distrib() fireman        return torch.equal(distrib, distrib**2) fireman fireman    def sample_archs(self, batch_size, probas, force_deterministic=False): fireman        """ fireman        Hook called by pytorch before each forward fireman        :param _: Current module fireman        :param input: Input given to the module's forward fireman        :return: fireman        """ fireman        deterministic = not self.training and self.deter_eval \ fireman                        or force_deterministic fireman        self._check_probas(probas, self.all_same) fireman fireman        # Check the compatibility with the batch_size fireman        if probas.size(0) != batch_size: fireman            if probas.size(0) != 1: fireman                raise ValueError('Sampling probabilities dimensions {} ' fireman                                 'doesn't match with batch size {}.' fireman                                 .format(probas.size(), batch_size)) fireman            # if not self.all_same: fireman            #     probas = probas.expand(batch_size, -1) fireman fireman        samplings = torch.zeros_like(probas) fireman        entropy = torch.zeros(0).to(samplings.device) fireman        log_probs = torch.zeros(0).to(samplings.device) fireman        if not self.all_same: fireman            samplings = samplings.repeat(batch_size, 1) fireman            entropy = entropy.repeat(batch_size, 1) fireman            log_probs = log_probs.repeat(batch_size, 1) fireman fireman        for mask in self.group_masks: fireman            if not any(mask): fireman                continue fireman            masked_probas = probas[mask.unsqueeze(0)].unsqueeze(0) fireman            if not self.all_same: fireman                masked_probas = masked_probas.repeat(batch_size, 1) fireman            distrib = Categorical(masked_probas) fireman fireman            if deterministic: fireman                index = masked_probas.argmax(1) fireman            else: fireman                index = distrib.sample() fireman fireman            new_sampling = f.one_hot(index, masked_probas.size(-1)).float() fireman fireman            expanded_mask = mask.expand_as(samplings) fireman            samplings[expanded_mask] = new_sampling.flatten() fireman fireman            entropy = torch.cat((entropy, distrib.entropy().unsqueeze(1)), 1) fireman            log_probs = torch.cat((log_probs, distrib.log_prob(index) fireman                                   .unsqueeze(1)), 1) fireman fireman        if self.all_same: fireman            samplings = samplings.expand(batch_size, -1) fireman fireman        # self._seq_probas.append(probas) fireman        self.distrib_entropies.append(entropy) fireman        self.log_probas.append(log_probs) fireman        return samplings fireman fireman    def nodes_to_prune(self, *args, **kwargs): fireman        distrib = self() fireman        arch = self.sample_archs(1, distrib, True) fireman        