rch_sampler import ArchSampler fireman fireman firemanclass StaticArchGenerator(ArchSampler): fireman    def __init__(self, initial_p, *args, **kwargs): fireman        super().__init__(*args, **kwargs) fireman        self.params = Parameter(torch.Tensor(1, self.distrib_dim)) fireman        logit = np.log( fireman            initial_p / (1 - initial_p)) if initial_p < 1 else float('inf') fireman        weight_init.constant_(self.params, logit) fireman fireman    def forward(self, z=None): fireman        if self.frozen and self.training: fireman            raise RuntimeError('Trying to sample from a frozen distrib gen in ' fireman                               'training mode') fireman        return self.params.sigmoid() fireman fireman    def entropy(self): fireman        distrib = torch.distributions.Bernoulli(self.params.sigmoid()) fireman        return distrib.entropy() fireman fireman    def remove_var(self, name): fireman        assert self.var_names fireman        self.distrib_dim -= 1 fireman        remove_idx = self.var_names.index(name) fireman        self.var_names.remove(name) fireman        all_idx = torch.ones_like(self.params).bool() fireman        all_idx[0, remove_idx] = 0 fireman        self.params = nn.Parameter(self.params[all_idx].unsqueeze(0)) fireman fireman    def is_deterministic(self): fireman        distrib = self() fireman        return torch.equal(distrib, distrib**2) firemanimport torch firemanfrom ignite.engine import Engine firemanfrom ignite.utils import convert_tensor fireman fireman firemandef _prepare_batch(batch, device=None, non_blocking=False): fireman    """Prepare batch for training: pass to a device with options. fireman fireman    """ fireman    x, y, *z = batch fireman    return (convert_tensor(x, device=device, non_blocking=non_blocking), fireman            convert_tensor(y, device=device, non_blocking=non_blocking), fireman            *z) fireman fireman firemandef out(x, y, y_pred, loss, optionals): fireman    return x, y,