             eval_loaders=self.eval_loaders, fireman                                          optimizer=self.optim, fireman                                          loss_fn=self.loss_fn, fireman                                          n_it_max=self.n_it_max, fireman                                          patience=self.patience, fireman                                          split_names=self.split_names, fireman                                          device=self.device, fireman                                          name=self.name, fireman                                          log_steps=self.log_steps, fireman                                          log_epoch=False, fireman                                          prepare_batch=self.prepare_batch) fireman            self.metrics = metrics fireman            self.best_state_dict = self.best['state_dict'] fireman            self.log_iterations = list(metrics['training_iteration'].values()) fireman fireman        res = {} fireman        # print('{} trying to pop {} ({})'.format(self.name, self.log_iterations, id(self.log_iterations))) fireman        # if len(self.log_iterations) == 0: fireman        #     print('wut?') fireman        cur_it = self.log_iterations.pop(0) fireman        # print('{} popping {} ({})'.format(self.name, cur_it, id(self.log_iterations))) fireman        # print(cur_it) fireman        for name, value_dict in self.metrics.items(): fireman            if cur_it in value_dict: fireman                res[name] = value_dict[cur_it] fireman            elif cur_it == 0: fireman                # Only metrics logged during the first iteration will be kept fireman                # by csv logger fireman                res[name] = float('nan') fireman fireman        if cur_it == self.best['iter']: fireman            res['should_checkpoint'] = True fireman fireman        if not self.log_iterations: fireman            res['done'] = True fireman fireman fireman fireman        # for k, v in metrics.items(): fireman        #     if isinstance(v, dict): fireman        #         res[k] = get_metric(v, log_iterations) fireman        #         keys.append(k) fireman        #     else: fireman                # raise ValueError(k) fireman                # print('GOT EXCEPTION !!!') fireman                # print('GOT EXCEPTION !!!') fireman                # print('GOT EXCEPTION !!!') fireman                # print('{}: {}'.format(k, v)) fireman                # print('GOT EXCEPTION !!!') fireman                # print('GOT EXCEPTION !!!') fireman                # print('GOT EXCEPTION !!!') fireman                # res[k] = v fireman        # raise ValueError(metrics) fireman        # res = {'unroll_columns': keys, fireman        #        'should_checkpoint': True, fireman        #        'done': True, fireman        #        **res} fireman        # res['mean_loss'] = res['Val nll'] fireman        # print('yoyoyow') fireman        # print(res.keys()) fireman        # print(res) fireman        # self.last = res fireman        # self.last_it = cur_it fireman        return res fireman firemandef get_metric(metric, steps, value=float('nan')): fireman    """ fireman    metric: dict of (step, value) pairs fireman    steps: all steps that should be logged fireman    value: values used to fill missing steps in metric fireman    """ fireman    return [metric.get(step, value) for step in steps] fireman fireman firemanclass TrainLLModel(BaseTrainLLModel): fireman    @staticmethod fireman    def _load_datasets(cur_data_path, cur_loss_fn, past_tasks): fireman        datasets = [] fireman        for split_path in cur_data_path: fireman            x, y = torch.load(split_path) fireman            datasets.append(TensorDataset(x, y)) fireman        return datasets fireman fireman firemanclass OSTrainLLModel(BaseOneShotTrainable): fireman    @staticmethod fireman    def _load_datasets(task, cur_loss_fn, past_tasks, transforms, normalize): fireman        return _load_datasets(task, transforms=transforms, fireman                              normalize=normalize) fireman        # datasets = [] fireman        # for split_path in cur_data_path: fireman        #     x, y = torch.load(split_path) fireman        #     datasets.append(TensorDataset(x, y)) fireman        # return datasets fireman fireman firemanclass MultiTaskTrainable(abc.ABC): fireman    @staticmethod fireman    def _load_datasets(cur_data_path, cur_loss_fn, past_tasks): fireman        all_tasks = past_tasks + [[cur_data_path, cur_loss_fn]] fireman        return get_multitask_dataset(all_tasks) fireman fireman    @staticmethod fireman    def _get_dataloaders(datasets, batch_sizes): fireman        train_batch_sampler = MTBatchSampler(datasets[0], batch_sizes[0], False, False) fireman        train_loader = DataLoader(datasets[0], fireman                                  batch_sampler=train_batch_sampler) fireman fireman        eval_batch_samplers = [MTBatchSampler(ds, batch_sizes[1], False, False) fireman                               for ds in datasets] fireman fireman        eval_loaders = [DataLoader(ds, batch_sampler=bs) fireman                        for ds, bs in zip(datasets, eval_batch_samplers)] fireman        return train_loader, eval_loaders fireman fireman firemanclass SimpleMultiTaskTrainable(MultiTaskTrainable, BaseTrainLLModel): fireman    pass fireman fireman firemanclass OSMultiTaskTrainable(MultiTaskTrainable, BaseOneShotTrainable): fireman    pass fireman fireman firemanclass MTBatchSampler(Sampler): fireman    def __init__(self, concat_dataset, batch_size, drop_last, patial_batches_ok): fireman        super(MTBatchSampler, self).__init__(concat_dataset) fireman        self.task_idx_bins = [] fireman        offset = 0 fireman        for ds in concat_dataset.datasets: fireman            self.task_idx_bins.append(np.arange(offset, offset + len(ds))) fireman            offset += len(ds) fireman fireman        if not isinstance(batch_size, int) or isinstance(batch_size, bool) or \ fireman                batch_size <= 0: fireman            raise ValueError("batch_size should be a positive integer value, " fireman                             "but got batch_size={}".format(batch_size)) fireman        if not isinstance(drop_last, bool): fireman            raise ValueError("drop_last should be a boolean value, but got " fireman                             "drop_last={}".format(drop_last)) fireman fireman        self.samplers = [SubsetRandomSampler(idx) for idx in self.task_idx_bins] fireman        self.batch_size = batch_size fireman        self.drop_last = drop_last fireman        self.partial_batches_ok = patial_batches_ok fireman fireman    def __iter__(self): fireman        iters = [iter(sub_samp) for sub_samp in self.samplers] fireman        batch = [] fireman        while iters: fireman            sampler_idx = torch.randint(len(iters), (1,)).item() fireman            sampler = iters[sampler_idx] fireman            for idx in sampler: fireman                batch.append(idx) fireman                if len(batch) == self.batch_size: fireman                    break fireman            if len(batch) == self.batch_size: fireman                # We have a full batch fireman                yield batch fireman                batch = [] fireman            elif len(batch) > 0 and not self.drop_last: fireman                # We have a partial batch, meaning that the selected sampler is fireman                # finished. fireman                iters.remove(sampler) fireman                if self.partial_batches_ok or not iters: fireman                    yield batch fireman                    batch = [] fireman            else: fireman                # We don't have a batch. Either the selected iterator was fireman                # empty or we have a partial batch but we are dropping it. fireman                iters.remove(sampler) fireman fireman    def __len__(self): fireman        if self.drop_last: fireman            return sum( fireman                len(sampler) // self.batch_size for sampler in self.samplers) fireman        else: fireman            return sum( fireman                (len(sampler) + self.batch_size - 1) // self.batch_size for fireman                sampler in self.samplers) fireman fireman firemandef convert_to_tune_search_space(search_space): fireman    if isinstance(search_space, list): fireman        first = search_space[0] fireman        if isinstance(first, numbers.Number): fireman            return tune.grid_search(search_space) fireman        elif isinstance(first, dict): fireman            return [convert_to_tune_search_space(itm) for itm in search_space] fireman        else: fireman            raise ValueError('Unknown list type: list<{}>'.format(type(first))) fireman    elif isinstance(search_space, dict): fireman        return {k: convert_to_tune_search_space(v) fireman                for k, v in search_space.items()} fireman    else: fireman        return search_space

class GradientReconstructor():
    """Instantiate a reconstruction algorithm."""

    def __init__(self, model, mean_std=(0.0, 1.0), config=DEFAULT_CONFIG, num_images=1):
        """Initialize with algorithm setup."""
        self.config = _validate_config(config)
        self.model = model
        self.setup = dict(device=next(model.parameters()).device, dtype=next(model.parameters()).dtype)

        self.mean_std = mean_std
        self.num_images = num_images

        if self.config['scoring_choice'] == 'inception':
            self.inception = InceptionScore(batch_size=1, setup=self.setup)

        self.loss_fn = torch.nn.CrossEntropyLoss(reduction='mean')
        self.iDLG = True

    def reconstruct(self, input_data, labels, img_shape=(3, 32, 32), dryrun=False, eval=True, tol=None):
        """Reconstruct image from gradient."""
        start_time = time.time()
        if eval:
            self.model.eval()


        stats = defaultdict(list)
        x = self._init_images(img_shape)
        scores = torch.zeros(self.config['restarts'])

        if labels is None:
            if self.num_images == 1 and self.iDLG:
                # iDLG trick:
                last_weight_min = torch.argmin(torch.sum(input_data[-2], dim=-1), dim=-1)
                labels = last_weight_min.detach().reshape((1,)).requires_grad_(False)
                self.reconstruct_label = False
            else:
                # DLG label recovery
                # However this also improves conditioning for some LBFGS cases
                self.reconstruct_label = True

                def loss_fn(pred, labels):
                    labels = torch.nn.functional.softmax(labels, dim=-1)
                    return torch.mean(torch.sum(- labels * torch.nn.functional.log_softmax(pred, dim=-1), 1))
                self.loss_fn = loss_fn
        else:
            assert labels.shape[0] == self.num_images
            self.reconstruct_label = False

        try:
            for trial in range(self.config['restarts']):
                x_trial, labels = self._run_trial(x[trial], input_data, labels, dryrun=dryrun)
                # Finalize
                scores[trial] = self._score_trial(x_trial, input_data, labels)
                x[trial] = x_trial
                if tol is not None and scores[trial] <= tol:
                    break
                if dryrun:
                    break
        except KeyboardInterrupt:
            print('Trial procedure manually interruped.')
            pass

        # Choose optimal result:
        if self.config['scoring_choice'] in ['pixelmean', 'pixelmedian']:
            x_optimal, stats = self._average_trials(x, labels, input_data, stats)
        else:
            print('Choosing optimal result ...')
            scores = scores[torch.isfinite(scores)]  # guard against NaN/-Inf scores?
            optimal_index = torch.argmin(scores)
            print(f'Optimal result score: {scores[optimal_index]:2.4f}')
            stats['opt'] = scores[optimal_index].item()
            x_optimal = x[optimal_index]

        print(f'Total time: {time.time()-start_time}.')
        return x_optimal.detach(), stats

    def _run_trial(self, x_trial, input_data, labels, dryrun=False):
        x_trial.requires_grad = True
        if self.reconstruct_label:
            output_test = self.model(x_trial)
            labels = torch.randn(output_test.shape[1]).to(**self.setup).requires_grad_(True)

            if self.config['optim'] == 'adam':
                optimizer = torch.optim.Adam([x_trial, labels], lr=self.config['lr'])
            elif self.config['optim'] == 'sgd':  # actually gd
                optimizer = torch.optim.SGD([x_trial, labels], lr=0.01, momentum=0.9, nesterov=True)
            elif self.config['optim'] == 'LBFGS':
                optimizer = torch.optim.LBFGS([x_trial, labels])
            else:
                raise ValueError()
        else:
            if self.config['optim'] == 'adam':
                optimizer = torch.optim.Adam([x_trial], lr=self.config['lr'])
            elif self.config['optim'] == 'sgd':  # actually gd
                optimizer = torch.optim.SGD([x_trial], lr=0.01, momentum=0.9, nesterov=True)
            elif self.config['optim'] == 'LBFGS':
                optimizer = torch.optim.LBFGS([x_trial])
            else:
                raise ValueError()

        max_iterations = self.config['max_iterations']
        dm, ds = self.mean_std
        if self.config['lr_decay']:
            scheduler = torch.optim.lr_scheduler.MultiStepLR(optimizer,
                                                             milestones=[max_iterations // 2.667, max_iterations // 1.6,

                                                                         max_iterations // 1.142], gamma=0.1)   # 3/8 5/8 7/8
        try:
            for iteration in range(max_iterations):
                closure = self._gradient_closure(optimizer, x_trial, input_data, labels)
                rec_loss = optimizer.step(closure)
                if self.config['lr_decay']:
                    scheduler.step()

                with torch.no_grad():
                    # Project into image space
                    if self.config['boxed']:
                        x_trial.data = torch.max(torch.min(x_trial, (1 - dm) / ds), -dm / ds)

                    if (iteration + 1 == max_iterations) or iteration % 500 == 0:
                        print(f'It: {iteration}. Rec. loss: {rec_loss.item():2.4f}.')

                    if (iteration + 1) % 500 == 0:
                        if self.config['filter'] == 'none':
                            pass
                        elif self.config['filter'] == 'median':
                            x_trial.data = MedianPool2d(kernel_size=3, stride=1, padding=1, same=False)(x_trial)
                        else:
                            raise ValueError()

                if dryrun:
                    break
        except KeyboardInterrupt:
            print(f'Recovery interrupted manually in iteration {iteration}!')
            pass
        return x_trial.detach(), labels

    def _gradient_closure(self, optimizer, x_trial, input_gradient, label):

        def closure():
            optimizer.zero_grad()
            self.model.zero_grad()
            loss = self.loss_fn(self.model(x_trial), label)
            gradient = torch.autograd.grad(loss, self.model.parameters(), create_graph=True)
            rec_loss = reconstruction_costs([gradient], input_gradient,
                                            cost_fn=self.config['cost_fn'], indices=self.config['indices'],
                                            weights=self.config['weights'])

            if self.config['total_variation'] > 0:
                rec_loss += self.config['total_variation'] * TV(x_trial)
            rec_loss.backward()
            if self.config['signed']:
                x_trial.grad.sign_()
            return rec_loss
        return closure

def reconstruction_costs(gradients, input_gradient, cost_fn='l2', indices='def', weights='equal'):
    """Input gradient is given data."""
    if isinstance(indices, list):
        pass
    elif indices == 'def':
        indices = torch.arange(len(input_gradient))
    elif indices == 'batch':
        indices = torch.randperm(len(input_gradient))[:8]
    elif indices == 'topk-1':
        _, indices = torch.topk(torch.stack([p.norm() for p in input_gradient], dim=0), 4)
    elif indices == 'top10':
        _, indices = torch.topk(torch.stack([p.norm() for p in input_gradient], dim=0), 10)
    elif indices == 'top50':
        _, indices = torch.topk(torch.stack([p.norm() for p in input_gradient], dim=0), 50)
    elif indices in ['first', 'first4']:
        indices = torch.arange(0, 4)
    elif indices == 'first5':
        indices = torch.arange(0, 5)
    elif indices == 'first10':
        indices = torch.arange(0, 10)
    elif indices == 'first50':
        indices = torch.arange(0, 50)
    elif indices == 'last5':
        indices = torch.arange(len(input_gradient))[-5:]
    elif indices == 'last10':
        indices = torch.arange(len(input_gradient))[-10:]
    elif indices == 'last50':
        indices = torch.arange(len(input_gradient))[-50:]
    else:
        raise ValueError()

    ex = input_gradient[0]
    if weights == 'linear':
        weights = torch.arange(len(input_gradient), 0, -1, dtype=ex.dtype, device=ex.device) / len(input_gradient)
    elif weights == 'exp':
        weights = torch.arange(len(input_gradient), 0, -1, dtype=ex.dtype, device=ex.device)
        weights = weights.softmax(dim=0)
        weights = weights / weights[0]
    else:
        weights = input_gradient[0].new_ones(len(input_gradient))

    total_costs = 0
    for trial_gradient in gradients:
        pnorm = [0, 0]
        costs = 0
        if indices == 'topk-2':
            _, indices = torch.topk(torch.stack([p.norm().detach() for p in trial_gradient], dim=0), 4)
        for i in indices:
            if cost_fn == 'l2':
                costs += ((trial_gradient[i] - input_gradient[i]).pow(2)).sum() * weights[i]
            elif cost_fn == 'l1':
                costs += ((trial_gradient[i] - input_gradient[i]).abs()).sum() * weights[i]
            elif cost_fn == 'max':
                costs += ((trial_gradient[i] - input_gradient[i]).abs()).max() * weights[i]
            elif cost_fn == 'sim':
                costs -= (trial_gradient[i] * input_gradient[i]).sum() * weights[i]
                pnorm[0] += trial_gradient[i].pow(2).sum() * weights[i]
                pnorm[1] += input_gradient[i].pow(2).sum() * weights[i]
            elif cost_fn == 'simlocal':
                costs += 1 - torch.nn.functional.cosine_similarity(trial_gradient[i].flatten(),
                                                                   input_gradient[i].flatten(),
                                                                   0, 1e-10) * weights[i]
        if cost_fn == 'sim':
            costs = 1 + costs / pnorm[0].sqrt() / pnorm[1].sqrt()

        # Accumulate final costs
        total_costs += costs
    return total_costs / len(gradients)

def total_variation(x):
    """Anisotropic TV."""
    dx = torch.mean(torch.abs(x[:, :, :, :-1] - x[:, :, :, 1:]))
    dy = torch.mean(torch.abs(x[:, :, :-1, :] - x[:, :, 1:, :]))
    return dx + dy
